export const PRODUCT = {

constituents: {
  packages: ["nonprofitcloud"],
  name: "Constituents",
  icon: "\u{1F465}",
  color: "#f59e0b",
  description: "The Constituents domain provides the shared foundation for people and organizations that interact with Nonprofit Cloud, including donors, volunteers, board members, program participants, case subjects, grant applicants, and partner organizations. Individuals are represented by Person Accounts, while organizations, households, and other groups use Business Accounts; relationships, hierarchies, household membership, and contact points add context to those records. Fundraising processes use constituent records for donor matching, gift transactions, soft credits, and specialized Contact Profile attributes, while program, case, volunteer, and grantmaking processes reference the same constituents. Administrators configure the account model during setup and protect constituent data through Salesforce permissions and sharing.",
  components: [
    {id:"person-accounts",name:"Person Accounts",icon:"\u{1F9D1}",desc:"Person Accounts represent individual constituents in Nonprofit Cloud, including donors, program participants, volunteers, and other stakeholders. They provide an individual account page where users can view constituent details, contact information, interactions, and fundraising summaries. Person Accounts are strongly recommended for Fundraising and Program Management, but they aren’t required for grantmakers that primarily make grants to organizations. Enabling Person Accounts is irreversible, and they aren’t supported for use with Nonprofit Success Pack.",tags:["Account","Contact","ContactProfile"],docs:["Nonprofit Cloud uses Person Accounts to represent individuals and can connect them to households, organizations, and other groups through Group Membership records. A Person Account can serve as the shared constituent record for fundraising, program delivery, case management, volunteer management, and grantmaking. Account pages can also present a chronological Timeline and permanent, searchable Interaction Summaries for stakeholder engagement.","Person Account pages can be configured with constituent contact information and fundraising components. Contact Point Address related records support multiple, seasonal, historical, primary, or undeliverable addresses, while automatic address synchronization can keep the account mailing address aligned with a Contact Point Address. Fundraising page configurations can also show donor giving summaries, RFM scores, relationship graphs, life events, and key information in a Summary Card.","Configure Person Accounts as part of the Nonprofit Cloud prerequisites and before setting up Fundraising features that depend on them. Consider the account model carefully because Person Accounts can’t be turned off after enablement. Organizations using Nonprofit Success Pack must follow the documented restriction that Person Accounts aren’t supported with NPSP."],docUrl:"https://help.salesforce.com/s/articleView?id=sales.account_person_enable.htm&type=5&language=en_US",connections:[{"planet":"households","desc":"Individuals are linked to households via Party Relationship Groups"},{"planet":"relationships","desc":"People form relationships with other constituents"},{"planet":"contact_points","desc":"Person accounts have addresses, emails, and phone numbers"}]},
    {id:"business-accounts",name:"Business Accounts",icon:"\u{1F3E2}",desc:"Business Accounts represent organizations, households, and other groups in Nonprofit Cloud. They support organization-level constituent activity, including fundraising and applications for grants. Business Account details can include contact and address information such as phone and billing address. Group Membership records can connect Business Accounts with individuals and other organizations.",tags:["Account"],docs:["Use Business Accounts for organizational constituents and for households or other groups in the Nonprofit Cloud account model. Grantmaking organizations that make most grants to organizations can use the Contact plus Business Account model instead of enabling Person Accounts. Account information can also be used in grant applications and funding award summaries to identify an applicant or recipient.","Business Account record pages can be configured for fundraising and relationship management. Account relationship graphs can use the Fundraising Business Account Relations template, while Summary Cards can display selected standard or custom fields. Business Accounts can also participate in donor workflows, including gift entry donor matching and donor document generation.","Store business contact addresses in account fields such as Billing Address. Nonprofit Cloud can also surface business milestones for a Business Account and provide a Timeline of stakeholder interactions. Access to Account records and their details follows configured Salesforce permissions and sharing."],connections:[{"planet":"relationships","desc":"Organizations form relationships with other organizations and individuals"},{"planet":"fundraising","desc":"Organizations can be donors and grant sources"}]},
    {id:"contact-profiles",name:"Contact Profiles",icon:"\u{1F4C7}",desc:"Contact Profiles extend constituent information with fundraising-oriented attributes in Nonprofit Cloud. A profile is associated with an Account and can store values such as donor classification and recurring donor type. Fundraising automation can use Contact Profile information when processing constituent roles and gift records. This keeps specialized fundraising details related to the shared constituent account.",tags:["ContactProfile"],docs:["Use a Contact Profile to maintain fundraising-specific information for a constituent associated with an Account. The profile can capture donor classification and recurring donor type without replacing the constituent’s core Account information. This separation lets fundraising processes use specialized attributes while other Nonprofit Cloud features continue to reference the same constituent.","Packaged fundraising automation can update an advancement type on a Contact Profile when a constituent role is inserted or updated, based on the rank of active constituent roles. Other advancement flows can populate Gift Transaction, Gift Commitment Schedule, and Gift Soft Credit fields from Contact Profile information. Those flows use the advancement type and the profile’s most recent graduation date."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_manage_donor_profiles.htm&type=5&language=en_US",connections:[{"planet":"gift_commitments","desc":"Contact profiles track recurring donor status"},{"planet":"fundraising","desc":"Donor profiles inform cultivation strategies"}]},
    {id:"account-hierarchies",name:"Account Hierarchies",icon:"\u{1F3D7}",desc:"Account Hierarchies organize related Account records through parent-child account relationships. They complement Group Membership records, which connect individuals and organizations to households and other groups. Relationship graphs can visualize Person Account or Business Account relations on donor profiles. Together, these structures help users understand how constituents and constituent groups are connected.",tags:["Account"],docs:["Use the Account ParentId relationship to place an Account beneath another Account in an account hierarchy. This structure is appropriate when the relationship between the records is organizational or hierarchical. Business Accounts can represent households and other groups within the configured Nonprofit Cloud account model.","Use Group Membership records when individuals and organizations must be connected to groups rather than represented only through an account parent relationship. Nonprofit Cloud setup includes enabling Person Accounts and configuring Group Memberships as foundational prerequisites. These connections support the broader stakeholder model used across fundraising, programs, cases, volunteers, and grantmaking.","Fundraising donor profiles can display account relationships by using Actionable Relationship Center graphs. Nonprofit Cloud provides separate default templates for Fundraising Business Account Relations and Fundraising Person Account Relations. Administrators create and configure the appropriate graph, then expose it on the donor profile for users."],connections:[{"planet":"relationships","desc":"Hierarchies complement relationship records between organizations"}]}
  ],
  dataFlow: ["Configure the Account model in setup, enable required constituent features, and secure record access with Salesforce permissions and sharing.","Create individuals as Person Accounts and organizations or groups as Business Accounts, then associate individuals with households and maintain account contact information.","Connect constituents through relationships, Group Memberships, and account hierarchies.","Classify donors with Contact Profiles, match them during gift entry, associate gift transactions with them, and attribute soft credits to appropriate constituents.","Use constituent records as program participants, case subjects, and volunteers across Nonprofit Cloud.","Register individual or organizational grant applicants as constituents for grantmaking processes."],
  connections: [{"planet":"households","desc":"Individuals belong to households"},{"planet":"relationships","desc":"Constituents have relationships"},{"planet":"contact_points","desc":"Accounts have contact information"},{"planet":"fundraising","desc":"Donors are constituents"},{"planet":"gift_transactions","desc":"Gift transactions belong to donors"},{"planet":"gift_entry","desc":"Donors matched during gift entry"},{"planet":"soft_credits","desc":"Soft credits attributed to constituents"},{"planet":"programs","desc":"Program participants are constituents"},{"planet":"case_management","desc":"Case subjects are constituents"},{"planet":"volunteers","desc":"Volunteers are constituents"},{"planet":"grantmaking","desc":"Grant applicants are constituents"},{"planet":"security","desc":"Constituent data access is secured"},{"planet":"setup","desc":"Account model configured in setup"}]
},

households: {
  packages: ["nonprofitcloud"],
  name: "Households & Groups",
  icon: "\u{1F3E0}",
  color: "#10b981",
  description: "Households & Groups models households and other affiliations through Party Relationship Groups and membership relationships in Nonprofit Cloud. Individuals belong to households through dated, role-based connections, and the model supports overlapping household or group affiliations. Household members can have additional inter-relationships and can share contact information while retaining constituent-specific addresses. Household address data can support outreach activities such as campaign mailings.",
  components: [
    {id:"party-relationship-groups",name:"Party Relationship Groups",icon:"\u{1F46A}",desc:"Party Relationship Groups provide a flexible way to represent households and other affiliations in Nonprofit Cloud. A group is associated with an account and can be classified by type, including Household, with start and end dates that define its duration. Individuals and organizations connect to groups through membership records, allowing a constituent to participate in more than one household or other group.",tags:["PartyRelationshipGroup"],docs:["Nonprofit Cloud uses Person Accounts to represent individuals and Business Accounts to represent households and other groups. A Party Relationship Group identifies a named group, associates it with an account, and records its type. Start and end dates support groups whose relevance or composition changes over time.","Membership connections associate individuals or organizations with a group rather than placing every constituent into a single fixed household structure. This approach supports overlapping affiliations, including membership in multiple households or other groups. The resulting group and relationship information can contribute to a unified understanding of stakeholders and their connections."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.group_membership_set_up.htm&type=5&language=en_US",connections:[{"planet":"constituents","desc":"Groups contain individual constituents as members"},{"planet":"relationships","desc":"Group members have inter-relationships"}]},
    {id:"household-membership",name:"Household Membership",icon:"\u{1F511}",desc:"Household Membership connects an individual to a household represented by a Party Relationship Group. Account Contact Relationship records capture the participating account and contact, membership roles, active status, and applicable dates. Household members can also have inter-relationships, and a person can belong to multiple groups when needed.",tags:["AccountContactRelationship"],docs:["Create household membership by connecting an individual to the account associated with the household group. The Account Contact Relationship identifies the account and contact and records whether the membership is active. Start and end dates preserve the period during which the membership applies.","Use roles such as Head of Household, Member, or Dependent to describe how an individual participates in the household. Because membership is maintained through relationship records, the same individual can be connected to more than one household or affinity group. Related relationship information can describe connections among household members in addition to their shared group affiliation."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.group_membership_how_nonprofit_cloud_models_groups_relationships.htm&type=5&language=en_US",connections:[{"planet":"constituents","desc":"Members are Person Account constituents"},{"planet":"relationships","desc":"Membership roles complement interpersonal relationships"}]},
    {id:"household-addressing",name:"Household Addressing",icon:"\u{1F4EC}",desc:"Household Addressing supports the use of household and constituent address information for outreach, including campaign mailings. Nonprofit Cloud uses contact address fields for constituents and account address fields for business contacts. Organizations can also track multiple or historical constituent addresses so communications use the address that is currently in effect.",tags:["PartyRelationshipGroup"],docs:["Address management keeps constituent contact information accurate and organized. For constituents, use contact fields such as Mailing Address; for business contacts, use account fields such as Billing Address. Household records can provide shared contact information while individual records retain constituent-specific details.","Constituents can have multiple addresses that apply at different times of the year, and organizations can retain historical addresses. Maintaining these records helps teams send outreach materials and gift acknowledgments to the address currently used by the constituent. Household address information can also support addressing decisions for campaign mailings."],connections:[{"planet":"contact_points","desc":"Household members share contact point addresses"},{"planet":"campaigns","desc":"Household addressing supports campaign mailings"}]}
  ],
  dataFlow: ["Create or identify the individual constituent records.","Create the household account and its Party Relationship Group.","Add household members with roles, active status, and membership dates.","Maintain member inter-relationships and any overlapping group affiliations.","Update shared and constituent-specific contact information.","Use current household addressing data for campaign mailings."],
  connections: [{"planet":"constituents","desc":"Individuals belong to households"},{"planet":"relationships","desc":"Household members have inter-relationships"},{"planet":"contact_points","desc":"Households share contact information"},{"planet":"campaigns","desc":"Household addressing for campaign mailings"}]
},

relationships: {
  packages: ["nonprofitcloud"],
  name: "Relationships",
  icon: "\u{1F91D}",
  color: "#8b5cf6",
  description: "Relationships in Nonprofit Cloud track connections among constituents, including individual-to-individual, individual-to-organization, and organization-to-organization ties. Contact relationships capture personal connections, while account relationships provide household, affiliation, partnership, and other organizational context. Configurable Party Role Relationships supply consistent relationship types and reciprocal labels. This connected view supports household understanding, soft credit decisions, fundraising engagement, and grantmaking analysis.",
  components: [
    {id:"contact-contact-relationships",name:"Contact Contact Relationships",icon:"\u{1F46B}",desc:"Contact Contact Relationships record connections between individual constituents, including spouses, parents and children, and colleagues. Each relationship identifies a contact, a related contact, and the role that characterizes their connection. Active status and start-date information support ongoing relationship tracking. These relationships can provide context for household membership, donor engagement, and soft credit decisions.",tags:["ContactContactRelationship"],docs:["Use Contact Contact Relationships to model personal connections between constituents. A relationship links the contact in ContactId to the contact in RelatedContactId. RoleId identifies the configured role that describes the connection, such as a family or professional relationship.","Use IsActive to indicate whether the relationship is current, and StartDate to record when it began. This information helps staff understand the people connected to a constituent when reviewing donor and stakeholder data. It can also inform household context and decisions about recognizing people who influenced a gift through soft credits."],connections:[{"planet":"constituents","desc":"Links individual Person Account records"},{"planet":"soft_credits","desc":"Relationships inform soft credit attribution for gifts"}]},
    {id:"account-contact-relationships",name:"Account Contact Relationships",icon:"\u{1F4BC}",desc:"Account Contact Relationships represent connections between individuals and organizations. Nonprofit Cloud can use Person Accounts for individuals and Business Accounts for households, other groups, and organizations. These connections help staff understand a constituent’s organizational affiliations and broader stakeholder context. They can support relationship-based fundraising and grantmaking work.",tags:["AccountContactRelationship"],docs:["Use Account Contact Relationships to capture how an individual is connected to an organization. In the Nonprofit Cloud data model, Person Accounts can represent individuals, while Business Accounts can represent households, groups, and organizations. Salesforce relationship and group-membership capabilities connect individuals and organizations to one another.","These relationships provide organizational context when staff evaluate or engage a constituent. Fundraising teams can use that context to understand professional affiliations and identify opportunities for deeper engagement. Grantmaking teams can also consider connections between people and applicant or recipient organizations."],connections:[{"planet":"constituents","desc":"Links individuals to organizations"},{"planet":"households","desc":"ACRs link household members to household groups"}]},
    {id:"account-account-relationships",name:"Account Account Relationships",icon:"\u{1F3E2}",desc:"Account Account Relationships model connections between organizations, households, and other account-based groups. They can represent organizational affiliations, partnerships, and related institutional ties. Each record identifies two accounts, assigns a configured role, and indicates whether the relationship is active. Account relationships can be displayed graphically on a donor profile to help users understand connected people and businesses.",tags:["AccountAccountRelationship"],docs:["Use Account Account Relationships to record a connection between the account in AccountId and the account in RelatedAccountId. RoleId identifies the configured role that characterizes the connection. IsActive indicates whether the organizational relationship is current.","Nonprofit Cloud can present account relationships through an Actionable Relationship Center graph on the donor profile. Actionable Relationship Center provides an interactive display that helps users understand relationships among people and businesses. This organizational context can inform fundraising engagement and decisions involving grant applicants or recipients."],connections:[{"planet":"constituents","desc":"Links organization accounts together"},{"planet":"grantmaking","desc":"Organization relationships inform grantmaking"}]},
    {id:"party-role-relationships",name:"Party Role Relationships",icon:"\u{1F3F7}",desc:"Party Role Relationships define the relationship types that can be applied to connections between parties in Nonprofit Cloud. Each definition has a name, a reciprocal label, a relationship type, and an active status. Reciprocal labels describe the relationship from the perspective of the related party. Administrators configure and activate these definitions during setup so relationship records use consistent terminology.",tags:["PartyRoleRelationship"],docs:["Use Party Role Relationships to establish the available relationship classifications for constituent and organization connections. Name identifies the role, while ReciprocalLabel provides the corresponding label from the other party’s perspective. RelationshipType categorizes the definition for relationship usage.","Use IsActive to control whether a relationship definition is available for current use. Configure these definitions in setup before applying roles to relationship records. Consistent role definitions help staff interpret personal, household, and organizational connections across Nonprofit Cloud."],connections:[{"planet":"setup","desc":"Relationship types are configured by admins in setup"}]}
  ],
  dataFlow: ["Configure active relationship types and reciprocal labels in setup.","Connect constituents through individual, household, and organizational relationship records.","Assign the appropriate role and record current status or start-date details where available.","Review household-member and organization connections in constituent profiles and relationship graphs.","Use relationship context to inform soft credit decisions, fundraising engagement, and grantmaking work."],
  connections: [{"planet":"constituents","desc":"Relationships connect constituents"},{"planet":"households","desc":"Household members have relationships"},{"planet":"soft_credits","desc":"Relationships inform soft credit decisions"},{"planet":"grantmaking","desc":"Organization relationships inform grants"},{"planet":"setup","desc":"Relationship types configured in setup"}]
},

contact_points: {
  packages: ["nonprofitcloud"],
  name: "Contact Information",
  icon: "\u{1F4DE}",
  color: "#06b6d4",
  description: "Contact Information in Nonprofit Cloud manages address, email, and phone records associated with constituent accounts. Multiple contact points can be maintained for an individual or organization, with a primary designation identifying the preferred record. Household members can share contact information, and current contact points support campaign outreach and constituent service. Address management also supports seasonal usage, undeliverable status, and synchronization with Person Account mailing addresses.",
  components: [
    {id:"contact-point-addresses",name:"Contact Point Addresses",icon:"\u{1F4CD}",desc:"Contact Point Addresses store mailing and physical address information associated with constituent accounts in Nonprofit Cloud. An account can have additional, primary, temporary, inactive, or seasonal addresses to support accurate correspondence. Users can identify the primary address and track addresses that are seasonal or undeliverable. These records support household contact information and address selection for campaign outreach.",tags:["ContactPointAddress"],docs:["Users add an address from the Contact Point Addresses related list on an account and provide a record name, address details, usage type, and primary designation. Supported usage examples include Home, Work, Temporary, and Inactive. Seasonal start and end information can identify when an address should be used, such as for a winter home or college dormitory.","Automatic Person Account Mailing Address Synchronization keeps the primary Contact Point Address and Person Account mailing address aligned when the required flow is configured and activated. Selecting Is Primary identifies the address for the donor profile and mailed outreach; removing the designation clears it from the Person Account mailing address fields. Administrators must provide users with appropriate access to the address, Is Primary, and Is Undeliverable fields on Contact Point Address and to the Person Account mailing address fields.","When returned mail indicates that an address is invalid, users can mark the Contact Point Address as undeliverable. If that record is also primary, automatic synchronization removes it from the Person Account mailing address to prevent further correspondence to that address. Before sending seasonal correspondence, users should review the seasonal dates and select the address appropriate for the mailing date."],connections:[{"planet":"constituents","desc":"Addresses belong to constituent accounts"},{"planet":"campaigns","desc":"Addresses used for direct mail campaigns"},{"planet":"households","desc":"Household members may share addresses"}]},
    {id:"contact-point-emails",name:"Contact Point Emails",icon:"\u{1F4E7}",desc:"Contact Point Emails store constituent email addresses associated with accounts in Nonprofit Cloud. Each record captures an email address and its type and can be designated as primary. Multiple contact records allow constituent contact information to be maintained separately rather than reduced to a single value. Current email information supports constituent service and campaign outreach.",tags:["ContactPointEmail"],docs:["Users can update constituent contact information while handling requests from existing or prospective donors. ContactPointEmail records associate an email address with an account through ParentId, classify it with EmailType, and identify a preferred record with IsPrimary. This information can be reviewed alongside other donor details when matching and supporting a constituent."],connections:[{"planet":"constituents","desc":"Emails belong to constituent accounts"},{"planet":"campaigns","desc":"Email addresses used for outreach"}]},
    {id:"contact-point-phones",name:"Contact Point Phones",icon:"\u{260E}",desc:"Contact Point Phones store constituent telephone numbers associated with accounts in Nonprofit Cloud. Each record captures a telephone number and phone type and can be marked as primary. Multiple phone records support maintaining distinct contact details for a constituent. Current phone information helps users respond to constituent requests and supports campaign outreach.",tags:["ContactPointPhone"],docs:["Users can review and update constituent contact information while responding to existing or prospective donors. ContactPointPhone records associate a telephone number with an account through ParentId, classify it with PhoneType, and identify a preferred record with IsPrimary. The records provide structured phone information when users search for and match a donor record during an interaction."],connections:[{"planet":"constituents","desc":"Phone numbers belong to constituent accounts"}]}
  ],
  dataFlow: ["Identify the constituent or household account that owns the contact information.","Create address, email, and phone contact point records for the account.","Classify each contact point and designate the appropriate primary record.","Maintain seasonal and undeliverable address details as circumstances change.","Keep shared household contact information current for household members.","Use current contact points for constituent service and campaign outreach."],
  connections: [{"planet":"constituents","desc":"Contact information belongs to accounts"},{"planet":"households","desc":"Household members share contact information"},{"planet":"campaigns","desc":"Contact points used for campaign outreach"}]
},

fundraising: {
  packages: ["nonprofitcloud"],
  name: "Fundraising Pipeline",
  icon: "\u{1F4B0}",
  color: "#ef4444",
  description: "The Fundraising Pipeline domain manages cultivation and solicitation for major gifts, inbound grants, and other significant donor asks in Nonprofit Cloud before they are formalized as gifts. Donors are represented as constituents, campaigns source fundraising activity, Action Plans organize cultivation steps, and opportunities progress through configurable sales processes with default gift designations and related contact roles. Successful opportunities connect to gift commitments and resulting gift transactions, while opportunity contact roles drive soft-credit recognition for constituents who influenced a gift. Fundraising settings are maintained in Setup, analytics support pipeline prioritization, Agentforce can generate draft gift proposals, and grant solicitations can use the same opportunity pipeline.",
  components: [
    {id:"opportunities",name:"Opportunities",icon:"\u{1F3AF}",desc:"Opportunities represent active fundraising asks for individual giving, major gifts, corporate sponsorships, and grants in Nonprofit Cloud. They track expected value, close date, probability, campaign source, account, record type, and progress through fundraising stages. Opportunities can carry default gift designations and connect successful solicitations to gift commitments and resulting gift transactions. Fundraisers can also use opportunity data to prioritize donor engagement and prepare AI-generated draft gift proposals.",tags:["Opportunity"],docs:["Use opportunities when the organization needs to track the solicitation that precedes a gift. Nonprofit Cloud supports tracking gifts for particular opportunities and campaigns, and a gift commitment can be connected to both records. Opportunities are especially relevant for major gifts, patterned multipayment solicitations, inbound grants, and solicited in-kind or donor-advised fund gifts.","Configure the Opportunity object to match the fundraising process. For inbound grant solicitation, the documentation recommends configuring a record type, stage values, and a Sales Process, along with grant-specific custom fields and a page layout. Opportunity records use the amount, stage, close date, and probability to describe the current ask and its expected outcome.","Associate gift default designations with an opportunity to direct related incoming gifts. When a commitment is created from or connected to the opportunity, its designation allocation can inherit from the associated opportunity before falling back to the campaign or organization-wide default. The opportunity can then remain connected to the gift commitment and the gift transactions produced through commitment processing."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_learn_about_nonprofit_cloud_fundraising.htm&type=5&language=en_US",connections:[{"planet":"gift_commitments","desc":"Won opportunities become gift commitments"},{"planet":"campaigns","desc":"Opportunities are sourced from campaigns"},{"planet":"designations","desc":"Opportunities can have default gift designations"}]},
    {id:"opportunity-contact-roles",name:"Opportunity Contact Roles",icon:"\u{1F464}",desc:"Opportunity Contact Roles associate multiple constituent contacts with a fundraising opportunity and describe how each person participates in the solicitation. A role can identify a primary donor, influencer, decision maker, or another relevant relationship, while IsPrimary identifies the principal contact. These relationships give fundraisers context for coordinating engagement around an ask. They also drive soft-credit recognition when a constituent influenced the resulting gift.",tags:["OpportunityContactRole"],docs:["Use Opportunity Contact Roles to connect constituent contacts to an opportunity rather than representing every participant as the legal donor. Each record references one opportunity and one contact, records the contact's role, and can designate that contact as primary. This structure supports fundraising opportunities involving several people with different responsibilities or types of influence.","Maintain these roles while cultivating and soliciting the opportunity so the relationship context remains available when the ask produces a gift. Nonprofit Cloud uses the opportunity contact-role relationships to drive soft credits, which recognize parties who influenced a donation without treating them as the legal donor. Soft credits support accurate recognition, strategic donor engagement, and constituent segmentation."],connections:[{"planet":"constituents","desc":"Contact roles reference person accounts"},{"planet":"soft_credits","desc":"Contact roles inform soft credit attribution"}]},
    {id:"sales-processes",name:"Sales Processes",icon:"\u{1F4C8}",desc:"Sales Processes define the stage values used to track opportunities through a fundraising pipeline in Nonprofit Cloud. They let organizations align opportunity progression with the solicitation process for major gifts, grants, and other tracked asks. Record types can associate different opportunity processes with different fundraising scenarios. Grant solicitation can use its own record type, stage values, Sales Process, custom fields, and page layout.",tags:["Opportunity"],docs:["Configure opportunity stages to represent the steps that fundraising staff use to develop and close an ask. Stage, close date, probability, and amount provide the core information needed to evaluate an opportunity's position and expected value. Fundraising analytics can then group opportunity value and donor counts by stage.","For grant solicitation, set up the process on the Opportunity object by defining a record type, stage values, and a Sales Process. Add grant-specific fields and a grant-specific Opportunity page layout when the organization needs to capture additional application or solicitation information. This approach allows grants to use the fundraising pipeline while retaining information specific to grant work.","Use Action Plans alongside the sales process when a solicitation requires a defined set of cultivation tasks. Action Plans can define required tasks for capital campaigns and other fundraising activities. The opportunity stage communicates pipeline progress, while the action plan organizes the work needed to advance the relationship."],connections:[{"planet":"setup","desc":"Sales processes are configured by admins"},{"planet":"action_plans","desc":"Stage transitions can trigger action plans"}]},
    {id:"fundraising-analytics",name:"Fundraising Analytics",icon:"\u{1F4CA}",desc:"Fundraising Analytics provides dashboards and metrics for evaluating donor opportunities, gift activity, and campaign performance in Nonprofit Cloud. The Major Donor Insights dashboard analyzes opportunity value and donor counts across pipeline stages for a selected period. Fundraising Intelligence dashboards can be embedded in Lightning Experience pages to improve access to these insights. Fundraisers use the results to identify high-value donors, prioritize follow-up, and refine engagement strategies.",tags:["Opportunity"],docs:["Use the Major Donor Insights dashboard in the Philanthropy and Partnerships app to analyze donor opportunities over a selected time period. The dashboard presents key fundraising metrics, opportunity value by stage, and the number of donors associated with each stage. Donor Opportunity Details help users prioritize outreach based on opportunity value, current stage, and the number of days since the last interaction.","Fundraising dashboards combine opportunity, commitment, transaction, and campaign information to calculate fundraising metrics. Gift transactions associated with a gift commitment and opportunity are categorized as Major Donor transactions, while campaign associations also contribute to Mass Market categorization. These categories support analysis of total funds raised, donors, campaign return on investment, cost-to-revenue ratio, opportunity value, and average donation amount.","The Fundraising Analytics App embeds its dashboards automatically in homepages when installed. If an organization uses customized homepages, an administrator can add the Fundraising Analytics Dashboard component with Lightning App Builder. Organizations with multiple data spaces must use the same data space where the Fundraising Data Streams were deployed.","Donor analysis can also use RFM scores based on recency, frequency, and monetary value. The Data Processing Engine updates these scores through a scheduled or manually run RFM Score Calculation job. Marketers and fundraisers can report on or segment constituents by their scores to develop campaigns and proposals suited to their giving patterns."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.npc_fr_set_up_rfm_scoring.htm&language=en_US",connections:[{"planet":"campaigns","desc":"Analytics track campaign effectiveness"},{"planet":"designations","desc":"Analytics show designation-level totals"}]}
  ],
  dataFlow: ["Identify donor constituents and source fundraising asks from campaigns or grant solicitation work.","Create opportunities, assign default designations, relate constituent contacts, and organize cultivation tasks with Action Plans.","Advance opportunities through the configured Sales Process while using analytics and Agentforce-generated gift proposals to support engagement.","Close successful opportunities and connect them to gift commitments with the appropriate campaign and designation allocations.","Process the commitments into gift transactions and create soft-credit recognition from the relevant opportunity contact roles.","Configure and maintain the required Fundraising settings in Setup."],
  connections: [{"planet":"constituents","desc":"Donors are constituents"},{"planet":"gift_commitments","desc":"Opportunities become commitments"},{"planet":"gift_transactions","desc":"Opportunities produce transactions"},{"planet":"campaigns","desc":"Campaigns source fundraising"},{"planet":"designations","desc":"Opportunities have default designations"},{"planet":"soft_credits","desc":"Opportunity contact roles drive soft credits"},{"planet":"agentforce","desc":"AI generates gift proposals"},{"planet":"action_plans","desc":"Action plans drive cultivation steps"},{"planet":"setup","desc":"Fundraising settings in setup"},{"planet":"grantmaking","desc":"Grants use the fundraising pipeline"}]
},

gift_commitments: {
  packages: ["nonprofitcloud"],
  name: "Gift Commitments",
  icon: "\u{1F4DD}",
  color: "#f97316",
  description: "Gift Commitments in Nonprofit Cloud manage donor promises for pledges, multipayment gifts, recurring donations, and in-kind contributions. A commitment can originate from gift entry or an opportunity, be attributed to a campaign, and be allocated to donor-selected gift designations. Recurring and custom schedules define expected payment timing and drive the creation and update of gift transactions. Lifecycle operations change amounts, dates, payment details, pauses, resumptions, or closure, while the Change Attribution Log records information used to attribute those modifications.",
  components: [
    {id:"commitment-records",name:"Commitment Records",icon:"\u{1F4DC}",desc:"Commitment records represent donor promises for one-time pledges, multipayment gifts, open-ended recurring gifts, and in-kind contributions in Nonprofit Cloud. Each record can identify the donor, commitment type, status, amount, start date, and associated campaign or opportunity. Commitments can also carry donor-selected designation allocations and soft credits for parties that influenced the gift. Users manage these records in the Fundraising app, where Kanban and Path are available for the GiftCommitment object.",tags:["GiftCommitment"],docs:["Create a gift commitment to record a one-time pledge, multipayment gift, or open-ended recurring gift, including the donor’s amount, schedule, and selected gift designations. A recurring commitment uses a recurring schedule when the donor pays a set amount at defined intervals, while a nonrecurring commitment paid in one or more installments uses a custom schedule. Gift Entry and the Gift Entry Grid can also create recurring gift commitments.","A commitment can be connected to an opportunity or campaign and allocated to one or more gift designations. Default designations can be inherited from the associated opportunity or campaign; if none are available, the organization-wide default designation receives the allocation. Users can modify the allocation ratios on the commitment, and unallocated percentages are assigned to the organization-wide default designation.","Nonprofit Cloud also uses gift commitments to represent donations of goods or services. An in-kind commitment can record the current and expected values of the assets and relevant transfer or maturity dates when those fields are included on the page layout. Organizations should distinguish acknowledgments from receipts and follow applicable requirements for recording nonmonetary gifts."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_gift_commitments.htm&type=5&language=en_US",connections:[{"planet":"fundraising","desc":"Commitments originate from fundraising opportunities"},{"planet":"gift_transactions","desc":"Commitments generate scheduled transactions"},{"planet":"designations","desc":"Commitments inherit default designations"}]},
    {id:"commitment-schedules",name:"Commitment Schedules",icon:"\u{1F4C5}",desc:"Commitment schedules define when and how payments associated with a gift commitment are expected. Nonprofit Cloud supports recurring schedules for payments made at regular intervals and custom schedules for nonrecurring commitments paid in one or more installments. Schedule details can include the frequency, installment amount, day of month, and effective date range. Creating or updating schedules from the Gift Commitment page automatically creates or updates related gift transactions.",tags:["GiftCommitmentSchedule"],docs:["For a recurring commitment, users provide a payment start date, an optional end date, a transaction period, an interval, and a recurring transaction amount. Monthly schedules can specify the day of the month on which the schedule runs. Users can also select a payment method, provide payment instrument details, and associate the schedule with a campaign.","For a nonrecurring commitment, users add custom schedule entries with a transaction due date, payment method, amount, and optional campaign. The selected schedule type controls the available scheduling options: recurring commitments use recurring periods, while commitments such as pledges or one-time gifts can use custom schedules. Standard validations help ensure that schedules are associated with appropriate commitments, have valid dates, and do not overlap where overlapping schedules are prohibited.","The Manage Gift Commitment Schedule flow creates and updates recurring and custom schedules. When schedules are managed from the Gift Commitment page, Nonprofit Cloud creates or updates the corresponding gift transactions; otherwise, users must maintain those transactions manually. Scheduled commitment processing can update commitments from their schedules and transactions, and administrators can monitor the resulting batch jobs."],connections:[{"planet":"gift_transactions","desc":"Schedules trigger gift transaction creation"},{"planet":"gift_entry","desc":"Gift entry can create new commitment schedules"}]},
    {id:"commitment-lifecycle",name:"Commitment Lifecycle",icon:"\u{1F504}",desc:"The commitment lifecycle covers changes to gift amounts, schedules, payment methods, active periods, and status. Nonprofit Cloud provides fundraising flows for upgrading or downgrading recurring commitments, pausing or resuming schedules, and closing commitments. Processing a change updates the commitment and associated schedule and transaction records. Donors can also perform supported lifecycle actions through a configured Donor Support Agent in an Experience Cloud site.",tags:["GiftCommitment","GiftCommitmentSchedule"],docs:["Users can upgrade or downgrade a recurring commitment by selecting a schedule and changing its amount or other schedule information. Effective start and end dates determine the portion of the schedule affected by the change. Existing unpaid transactions with due dates in that effective period are removed when the commitment is processed so that associated records can be regenerated from the updated schedule.","A recurring schedule can be paused for a specified period and later resumed. If a schedule is paused after its start date, Nonprofit Cloud splits the schedule and creates a Pause Transactions schedule for the selected period. Payment methods and payment instrument details can also be changed with effective dates, an optional update reason, and an optional campaign.","Close a commitment when it no longer needs to be tracked. For unpaid or failed transactions, closing sets the resulting status according to the commitment’s formal commitment type: transactions for a verbal commitment are canceled, while transactions for a written commitment are written off. With the Manage Gift Commitments subagent configured, donors can pause, resume, permanently close, or change the amount of eligible recurring commitments from an Experience Cloud donor portal."],connections:[{"planet":"gift_transactions","desc":"Lifecycle changes affect future transactions"},{"planet":"campaigns","desc":"Upgrades can be attributed to campaigns"}]},
    {id:"change-attribution-log",name:"Change Attribution Log",icon:"\u{1F4D3}",desc:"The Change Attribution Log associates a recorded commitment change with the affected gift commitment. Its data identifies the change type and date and can capture the per-day amount change, campaign, and outreach source code related to the modification. This information supports attribution of lifecycle changes to fundraising outreach. Access to the log is also required when configuring the Donor Support Agent to manage commitments.",tags:["GiftCommitmentChangeAttributionLog"],docs:["A GiftCommitmentChangeAttributionLog record links a change to its GiftCommitment and classifies it with a change type and change date. The record can store the per-day amount change associated with the modification. Campaign and outreach source code references provide fundraising attribution for the recorded change.","The Change Attribution Log participates in donor-managed commitment operations performed through the Manage Gift Commitments subagent. The cloned FundraisingExperienceCloud permission set used by the agent requires read, create, and delete access to the Gift Commitment Change Attribution Log. The same configuration requires access to Gift Commitment and Gift Commitment Schedule records so the supported changes can be completed."],connections:[{"planet":"campaigns","desc":"Changes are attributed to campaigns that influenced them"}]}
  ],
  dataFlow: ["Convert an opportunity into a gift commitment or create the commitment through gift entry.","Attribute the commitment to a campaign and allocate its amount to gift designations.","Define recurring or custom commitment schedules with amounts and effective dates.","Process the schedules to generate and update related gift transactions.","Apply lifecycle changes and record their attribution in the Change Attribution Log."],
  connections: [{"planet":"fundraising","desc":"Opportunities become commitments"},{"planet":"gift_transactions","desc":"Commitments generate transactions"},{"planet":"gift_entry","desc":"Gift entry creates commitments"},{"planet":"designations","desc":"Commitments allocated to designations"},{"planet":"campaigns","desc":"Commitments attributed to campaigns"}]
},

gift_transactions: {
  packages: ["nonprofitcloud"],
  name: "Gift Transactions",
  icon: "\u{1F4B3}",
  color: "#ec4899",
  description: "Gift Transactions in Nonprofit Cloud record received gifts and payments as individual transactions, including one-time donations, installments that fulfill gift commitments, and matching gifts linked to their initial donations. Transactions are created or updated through gift entry and can result from broader fundraising activity, with each donor represented by a constituent account. They can be attributed to campaigns, allocated to gift designations, and associated with gift soft credits for constituents who influenced the donation. Transaction records also support payment details, acknowledgment tracking, and full or partial refunds that preserve the gift's history.",
  components: [
    {id:"transaction-records",name:"Transaction Records",icon:"\u{1F9FE}",desc:"Transaction Records",tags:["GiftTransaction"],docs:["Gift transactions track donations received as one-time gifts or installments that fulfill gift commitments. A transaction can be attributed to a donor, gift commitment, campaign, and outreach source code. Donors can provide payment through means such as cash, checks, stocks, or other assets. Matching gifts are represented by gift transactions and can be linked to the initial donations they match.","Nonprofit Cloud automatically creates or updates gift transactions when gift entries are processed. It also creates transactions when users schedule and process gift commitments, with a transaction representing each scheduled installment. Users can manually create a transaction when necessary, select an individual or organizational donor, enter payment information and the original amount, and backdate the transaction to the check date or received date.","Transaction status reflects payment processing and is subject to permitted status transitions. Gift entries paid by cash or check produce paid transactions, while other payment methods produce pending transactions by default. Users can review upcoming, missed, failed, paid, and refunded transactions from the associated gift commitment. Gift transactions support Path and Kanban views, and selected validations can be paused during bulk data migrations.","Transaction amounts can be allocated among donor-selected designations, with any unallocated remainder assigned to the organization-wide default designation. Transactions can also carry soft credits for constituents who influenced a gift, including matching donors or tribute honorees. Campaign and outreach source code attribution supports analysis of the fundraising activity that produced the transaction."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_gift_transactions.htm&type=5&language=en_US",connections:[{"planet":"gift_commitments","desc":"Transactions fulfill commitment installments"},{"planet":"designations","desc":"Transactions are allocated to designations"},{"planet":"soft_credits","desc":"Transactions can have soft credit recipients"},{"planet":"campaigns","desc":"Transactions attributed to campaigns"}]},
    {id:"payment-instruments",name:"Payment Instruments",icon:"\u{1F4B1}",desc:"Payment Instruments",tags:["PaymentInstrument"],docs:["Payment instruments store payment details used with gift commitment schedules and their associated transactions. When users select ACH or credit card as the payment method and provide at least the last four digits, Nonprofit Cloud adds a payment instrument lookup to the schedule. If a matching payment instrument does not already exist, Nonprofit Cloud creates one.","Users can provide payment instrument information while creating a recurring or non-recurring gift commitment schedule, manually entering a gift transaction, or changing the payment method for a recurring commitment. Supported details described in the payment workflows include the payment method, last four digits, and expiration date. A payment method change can apply to a selected effective period, after which commitment processing updates the associated records.","Donor support users can verify payment instrument details for gift transactions and update constituent payment methods and payment information. Payment instruments are optional for recurring gifts in the fundraising data model. Their use associates reusable payment details with the donor account while gift transactions continue to record the individual payments."],connections:[{"planet":"gift_commitments","desc":"Payment instruments link to commitment schedules"}]},
    {id:"refund-processing",name:"Refund Processing",icon:"\u{1F501}",desc:"Refund Processing",tags:["GiftTransaction"],docs:["Refund processing returns all or part of a paid gift amount to the donor. A refund can correct a gift entry mistake or honor a donor's request to reverse a gift. Nonprofit Cloud creates the refund in association with the original gift transaction so that the complete transaction history is retained.","Users begin a refund from the paid gift transaction that is being reversed and can provide either a full or partial refund. The transaction's current amount and status govern subsequent status changes. In particular, users can't change the status of a fully refunded transaction.","Refunded activity remains available with other transaction information for review. The gift commitment details page can show recently refunded transactions alongside upcoming, missed, failed, and paid transactions. Gift Refund and Gift Transaction records also support Path, while both record types are available for Kanban list views."],connections:[{"planet":"designations","desc":"Refunds adjust designation allocation amounts"}]},
    {id:"acknowledgments",name:"Acknowledgments",icon:"\u{2709}",desc:"Acknowledgments",tags:["GiftTransaction"],docs:["Nonprofit Cloud uses customizable templates and Salesforce DocGen to create personalized gift acknowledgments and tax receipts. Organizations can generate a receipt for a single donor or produce acknowledgments in batches. Generation can also update the acknowledgment status on the included gift transaction records.","For a single receipt, users work from an account, select a document template, and filter transactions by a date range. They can optionally filter by transaction status and acknowledgment status, then choose whether to update the acknowledgment status of matching transactions. When generation finishes, the resulting PDF is available from the related files on the Document Generation Query Result record.","Batch generation lets users select a transaction date range and add filters based on Gift Transaction lookup objects or Gift Designation. Users can exclude already acknowledged transactions, update acknowledgment and tax receipt statuses after the DocGen job completes, and optionally include one Gift Transaction custom field that is also present in the template. A batch can also produce a donor report for mailing and review purposes.","Administrators enable server-side document generation, provide users with the required DocGen access, and add acknowledgment and tax receipt templates. Salesforce supplies sample templates for batch acknowledgments and single-donation tax receipts that organizations can customize with their logo, currency symbols, closing, and signature block. Organizations that accept multiple currencies can maintain separate templates and filter batches for the currency represented by each template."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_gift_entry_processing.htm&type=5&language=en_US",connections:[{"planet":"constituents","desc":"Acknowledgments sent to donor accounts"},{"planet":"campaigns","desc":"Campaign-specific acknowledgment templates"}]}
  ],
  dataFlow: ["Advance fundraising activity and identify the constituent account that made the gift.","Process the gift through gift entry to create or update its GiftTransaction record.","Apply the transaction to a gift commitment when it fulfills a scheduled or outstanding payment.","Attribute the transaction to campaigns and allocate its amount among gift designations.","Add gift soft credits for constituents who influenced the donation, then update payment and acknowledgment status as processing proceeds.","Create a full or partial refund against a paid transaction when needed, preserving the complete transaction history."],
  connections: [{"planet":"gift_commitments","desc":"Transactions fulfill commitments"},{"planet":"gift_entry","desc":"Gift entry creates transactions"},{"planet":"designations","desc":"Transactions linked to designations"},{"planet":"soft_credits","desc":"Transactions have soft credits"},{"planet":"campaigns","desc":"Transactions attributed to campaigns"},{"planet":"constituents","desc":"Donors are constituent accounts"},{"planet":"fundraising","desc":"Pipeline leads to transactions"}]
},

gift_entry: {
  packages: ["nonprofitcloud"],
  name: "Gift Entry & Processing",
  icon: "\u{1F4DD}",
  color: "#d946ef",
  description: "Gift Entry & Processing provides Nonprofit Cloud interfaces and batch workflows for recording, validating, and processing donations. The Gift Entry Window supports complete single-gift entry, while the Gift Entry Grid provides configurable tabular entry for a single gift or batches of up to 200 rows. Gift Batches apply shared templates and defaults, support dry runs and error correction, and process entries together. CSV Data Management extends the batch workflow to high-volume donation imports.",
  components: [
    {id:"gift-entry-window",name:"Gift Entry Window",icon:"\u{1F5BC}",desc:"The Gift Entry Window is the standard Nonprofit Cloud form for recording a standalone gift or adding an entry to an unprocessed batch. It can create a gift transaction, create a recurring gift commitment with its first transaction, or apply a payment to a matching active commitment. The same form captures donors, designations, campaign attribution, outreach source codes, soft credits, payment details, and mapped custom fields.",tags:["GiftEntry"],docs:["Users open the Gift Entry Window from Gift Entries, an Account record, or an unprocessed Gift Batch. They select an individual or organizational or household gift type, then select an existing donor or add one by name or donor ID. The form also captures the gift received date, amount, and payment method, and the received date can reflect the date on a check or the date the gift was received. A saved standalone entry is processed immediately.","The window can create a new recurring gift commitment by capturing its effective dates, transaction period, interval, and recurring day. It can also match the gift to an existing active commitment when the donor matches and an unpaid transaction falls within the configured Installment Extension Day Count window. A single gift entry can pay only one gift transaction and can't be applied across multiple transactions. After a commitment is applied to an entry, it can't be removed from that entry.","Users can enter an outreach source code, which automatically populates the associated campaign, and allocate the gift among as many as 50 designations. The window also accepts soft-credit details and displays mapped custom fields in an Additional Fields section. Custom fields used during gift entry shouldn't be marked as required in their field properties. For batch entry, Set As Default carries the current values into the next gift entry."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_gift_entry_processing.htm&type=5&language=en_US",connections:[{"planet":"gift_transactions","desc":"Gift entry creates gift transaction records"},{"planet":"gift_commitments","desc":"Gift entry can create new commitments"},{"planet":"designations","desc":"Designations applied during entry"}]},
    {id:"gift-entry-grid",name:"Gift Entry Grid",icon:"\u{1F4CA}",desc:"The Gift Entry Grid is a configurable tabular interface for rapidly recording a single gift or multiple gifts in a batch. Users can key across cells to capture donors, commitments, campaign and source-code attribution, designations, soft credits, and other gift information. Nonprofit Cloud supports up to 200 rows and provides templates, modals, and custom Lightning web components for tailoring the experience.",tags:["GiftEntry","GiftBatchTemplate"],docs:["Users can open the Gift Entry Grid from a gift batch, the Gift Entries list, or an Account page. A single gift starts with one row; a batch displays its expected number of rows or ten rows by default when no expected count is provided. Users can select, create, or edit a donor and then complete the remaining gift information across the row. Rows can be added or removed, although rows backed by already-created gift entry records can't be removed.","The grid can create recurring gift commitments and match gift transactions to existing commitments. It also captures outreach source codes, campaigns, designations, and soft credits, and supports up to 50 designations for each gift transaction. Custom fields mapped to Gift Transaction appear as columns, while mapped Account, Gift Commitment, and Gift Commitment Schedule fields appear in their corresponding detail windows. Nonprofit Cloud recommends using the grid in console view to avoid cache errors.","Administrators enable the Gift Entry Grid in Fundraising settings and configure multiple templates for different fundraising scenarios. Template columns can be reordered, relabeled, resized, hidden, required, or based on Gift Entry fields or Lightning web components. Templates can also open field or custom-component modals from columns, and the default single-entry template can display a conditional post-processing component after processing. Customization supports post-processing modals, column modals, and cell display or edit components.","For a single row, users select Process Gift or Process & New. Batch users can save work, run a dry run, and explicitly process the batch. If an entry encounters an error, Nonprofit Cloud posts the message to the gift processing result shown for that entry, and users can reopen the grid to correct affected rows. Deleting a gift entry doesn't automatically delete its related gift transaction."],connections:[{"planet":"gift_transactions","desc":"Grid creates multiple gift transactions"},{"planet":"constituents","desc":"Donors looked up or created during entry"}]},
    {id:"gift-batches",name:"Gift Batches",icon:"\u{1F4E6}",desc:"Gift Batches group multiple gift entries so that Nonprofit Cloud can validate and process them together. Each batch uses an associated template that defines the available fields and their display order. Batch defaults, expected totals, dry runs, processing statuses, and entry-level results support efficient review and correction.",tags:["GiftBatch","GiftBatchTemplate"],docs:["Users create a Gift Batch and select the default or an available custom screen template. The template provides a common set and order of fields for entries in that batch. Users can also provide expected gift count and estimated value information for validation during processing. After saving the batch, they add gift entries and process the collection together.","Set Batch Defaults applies common values to new and empty rows in the Gift Entry Grid. Defaults can include the gift received date, amount, payment method, outreach source code, campaign, designations, and soft credits, but they can't be assigned to read-only fields. Users can save the defaults and close the batch or continue directly to entry. When using the grid, rows are removed through the Gift Entries related list on the batch.","Batch entries aren't processed merely by saving them. Users can first run Batch Dry Run to simulate processing, then explicitly select Process Batch and refresh to review the resulting status. Processing errors are recorded on the affected gift entries so that users can edit and retry them, and successful batch completion requires every entry to process without errors."],connections:[{"planet":"gift_transactions","desc":"Batch processing creates transactions in bulk"}]},
    {id:"csv-import",name:"CSV Data Import",icon:"\u{1F4C4}",desc:"CSV Data Import loads large volumes of donation data into Nonprofit Cloud through CSV Data Management and a Gift Batch. Each imported row is associated with the target batch by its Batch ID. The resulting gift entries use the normal batch review, dry-run, correction, and processing workflow.",tags:["GiftBatch","GiftEntry"],docs:["Users first create a Gift Batch and copy its Batch ID. After preparing the CSV file, they add a Batch ID column and place that value in every gift-entry row intended for the batch. They then import the file through CSV Data Management. This approach reduces manual entry and the associated risk of data-entry errors.","The import creates gift entries associated with the specified batch rather than completing gift processing by itself. Users review the imported entries and process the Gift Batch using the standard batch workflow. A dry run can identify processing problems before explicit processing, and entry-level results support correction of errors. Access requires the documented CSV import permission and Fundraising access for creating and processing the batch."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.csv_file_import.htm&type=5&language=en_US",connections:[{"planet":"gift_transactions","desc":"Imported entries become gift transactions after processing"}]}
  ],
  dataFlow: ["Identify or create the donor during gift entry, using Agentforce for Nonprofit Cloud assistance where applicable.","Capture the amount, payment method, campaign, outreach source code, designations, and soft credits.","Create a gift commitment or match the entry to an eligible commitment and scheduled transaction.","Save and process a standalone entry, or collect entries in a Gift Batch through the grid or CSV import.","Run a batch dry run, review processing results, and correct entries with errors.","Process the entries to create gift transactions and update the related commitment fulfillment records."],
  connections: [{"planet":"gift_transactions","desc":"Gift entry creates transactions"},{"planet":"gift_commitments","desc":"Gift entry creates and matches commitments"},{"planet":"constituents","desc":"Donors entered or matched during gift entry"},{"planet":"designations","desc":"Designations applied during entry"},{"planet":"campaigns","desc":"Campaign and source code set during entry"},{"planet":"agentforce","desc":"AI assists gift data entry"}]
},

designations: {
  packages: ["nonprofitcloud"],
  name: "Gift Designations",
  icon: "\u{1F3F7}",
  color: "#14b8a6",
  description: "Gift Designations control how donation amounts are allocated to specific funds and purposes in Nonprofit Cloud. Default designations on campaigns, opportunities, and gift commitments provide inherited allocations, while transaction designations record how each payment is split. Hierarchical logic selects the applicable defaults during gift entry and assigns any unallocated amount to the organization-wide default. Data Processing Engine rollups summarize designation activity for fundraising analysis and connected impact reporting.",
  components: [
    {id:"gift-designations",name:"Gift Designations",icon:"\u{1F4CB}",desc:"Gift Designations in Nonprofit Cloud represent funds established for specific donor-directed purposes, such as relief or community programs. Organizations create active designations and identify one designation as the organization-wide default for unrestricted gift amounts. Designations can be associated with gift commitments, campaigns, and opportunities so that related gifts are allocated automatically. Existing allocations remain unchanged if the organization-wide default is replaced.",tags:["GiftDesignation"],docs:["Create a gift designation from the Gift Designations area and provide a name that identifies the fund or purpose. Mark the designation active so that it can be allocated when gift entries are processed; new designations are saved as active even when Active isn't selected during creation. Select Default when the designation is intended to receive unrestricted gift amounts. Only one gift designation can be the organization-wide default.","Every gift requires at least one allocated designation. If no other designation is defined, or if defined allocation percentages total less than 100%, Nonprofit Cloud assigns the remaining amount to the organization-wide default. Because processing many records under one designation can cause parent-child data skew, organizations should review record volume and create default designations as necessary. Changing the organization-wide default affects only new allocations and doesn't modify existing gift allocations."],connections:[{"planet":"gift_transactions","desc":"Transactions are allocated to designations"},{"planet":"campaigns","desc":"Campaigns can have default designations"},{"planet":"fundraising","desc":"Opportunities link to designations"}]},
    {id:"transaction-designations",name:"Transaction Designations",icon:"\u{1F517}",desc:"Transaction Designations allocate a gift transaction across one or more donor-selected funds in Nonprofit Cloud. A transaction normally inherits designations through gift entry or from its associated gift commitment, but users can add new allocations or override inherited ones. Each allocation records an amount or percentage for the relationship between the transaction and designation. Any unallocated percentage is assigned automatically to the organization-wide default designation.",tags:["GiftTransactionDesignation"],docs:["Users manage allocations from a gift transaction by opening Manage Gift Transaction Designations and adding or modifying rows. The combined percentages can be equal to or less than 100%, and each transaction can have up to 50 designations. If the allocations total less than 100%, Nonprofit Cloud allocates the remaining gift amount to the organization-wide default designation. To preserve accurate record rollups, users shouldn't change a gift transaction's currency after associating it with a transaction designation.","Gift entry can prepopulate transaction designations according to the applicable inheritance hierarchy, and users can review or update them before saving. For a one-time gift entry, designations come from the campaign when available; otherwise, the organization-wide default is used during processing. For an entry matched to a commitment, Nonprofit Cloud first considers designations on the selected transaction, followed by defaults from the transaction campaign, matching commitment, related opportunity, commitment campaign, and organization-wide default. Overriding the campaign during gift entry causes the gift entry's default designations to be used instead of this hierarchy.","When a gift batch is processed, Nonprofit Cloud creates gift transaction designation records for its gift entries. If a gift is allocated to multiple designations, processing splits the gift and creates multiple records according to the percentages and amounts entered. Gift Transaction Designation amounts and names can also be included in supported acknowledgment documents. This preserves the allocation detail associated with each payment."],connections:[{"planet":"gift_transactions","desc":"Each transaction can have multiple designation allocations"}]},
    {id:"default-designations",name:"Default Designations",icon:"\u{2B50}",desc:"Default Designations define how incoming gifts inherit allocations from fundraising records in Nonprofit Cloud. They can be associated with campaigns, opportunities, and gift commitments, and commitment defaults can be reviewed or changed from the commitment record. Hierarchical logic selects the available source for a gift entry or transaction while permitting a manual override. The organization-wide default fills any allocation that isn't otherwise assigned.",tags:["GiftDefaultDesignation"],docs:["From a gift commitment, users can open Manage Gift Default Designations to review defaults inherited from the associated opportunity or campaign. If neither provides a default, the organization-wide default appears with a 100% allocation. Users can add rows or change allocation ratios, provided the combined percentage is no more than 100%. Administrators can expose the Gift Default Designations related list on Campaign and Opportunity records so their allocations can be managed there.","Hierarchical logic determines the default designations inherited by commitments and the transaction designations inherited by gift transactions. A transaction associated with a commitment inherits that commitment's default designations unless a more applicable source or manual override is used during gift entry. When no defaults exist, the full amount is assigned to the organization-wide default; when defaults total less than 100%, the remaining percentage is assigned there. Commitment changes can also use default designations to attribute a commitment and its transactions across multiple campaigns according to the ratio in which those campaigns influenced the gift amount."],connections:[{"planet":"campaigns","desc":"Campaigns define default designations for sourced gifts"},{"planet":"gift_commitments","desc":"Commitments inherit designations from opportunities and campaigns"},{"planet":"gift_entry","desc":"Gift entry inherits default designations"}]},
    {id:"designation-reporting",name:"Designation Reporting",icon:"\u{1F4CA}",desc:"Designation Reporting surfaces giving metrics for designated funds in the Philanthropy and Partnerships app in Nonprofit Cloud. The Gift Designation Summary appears on the Gift Designation page after the required rollups are configured. Data Processing Engine definitions calculate and refresh designation-related rollups, with nightly recalculation provided by default and customizable scheduling available. Designation allocation data can also feed impact reporting for connected outcomes analysis.",tags:["GiftDesignation"],docs:["The Philanthropy and Partnerships app provides a Gift Designation Summary on each Gift Designation page. If the summary isn't visible, the required rollup setup may not have been completed. The summary presents gift-designation metrics at a glance alongside the app's broader donor and giving metrics. Designation data can also support connected impact reporting that relates funding allocations to outcomes.","To configure fundraising rollups, administrators enable Data Pipelines and clone and activate the supplied GiftDesignation Data Processing Engine template along with the other required fundraising templates. Definitions can be run manually with calendar date inputs, and Salesforce recalculates rollups nightly by default. Administrators can customize the Data Processing Engine schedule or use a schedule-triggered flow with the Manage Fundraising DPE Definitions invocable action to automate updates. Users running or configuring the definitions need access to the objects and fields used by them."],connections:[{"planet":"outcomes","desc":"Designation data supports impact and outcome reporting"}]}
  ],
  dataFlow: ["Create active gift designations and select the organization-wide default.","Assign default designations to campaigns, opportunities, and gift commitments.","Inherit the applicable defaults when commitments and gift entries are created or matched.","Review or override allocations during gift entry and transaction processing.","Create transaction designation records that split each payment by amount and percentage.","Run Data Processing Engine rollups and use designation results in fundraising and impact reporting."],
  connections: [{"planet":"gift_transactions","desc":"Transactions allocated to designations"},{"planet":"gift_commitments","desc":"Commitments inherit designations"},{"planet":"fundraising","desc":"Opportunities link to designations"},{"planet":"campaigns","desc":"Campaigns have default designations"},{"planet":"gift_entry","desc":"Gift entry applies designations"},{"planet":"outcomes","desc":"Designation data feeds impact reporting"},{"planet":"setup","desc":"DPE calculates designation rollups"}]
},

soft_credits: {
  packages: ["nonprofitcloud"],
  name: "Soft Credits",
  icon: "\u{1F31F}",
  color: "#a855f7",
  description: "Soft Credits in Nonprofit Cloud provide a consistent way to recognize constituents who influenced a gift without treating them as the primary donor. GiftSoftCredit records attribute amounts and roles to constituents on Gift Transactions, while Gift Commitment defaults can apply the same attribution across the commitment’s gifts. Constituent relationships inform attribution, and opportunity contact roles in Fundraising drive soft-credit recognition. Soft-credit data supports gift entry, donor engagement, segmentation, donor portals, and fundraising rollups.",
  components: [
    {id:"gift-soft-credits",name:"Gift Soft Credits",icon:"\u{2728}",desc:"Gift Soft Credits recognize people, businesses, or household members who influenced a gift without identifying them as the primary donor. Users can record credits during gift entry, as defaults on a Gift Commitment, or directly on a Gift Transaction. Each credit identifies a recipient, an amount or percentage, and a recipient role. The resulting records support donor engagement, segmentation, and fundraising rollups.",tags:["GiftSoftCredit"],docs:["Users with the FundraisingAccess permission set can add a default soft credit from the Gift Default Soft Credits related list on a Gift Commitment. They select the recipient, enter either an amount or percentage, and choose the recipient’s role. A default soft credit applies to all gifts that are part of that commitment, and its percentage can be greater than 100 percent.","A soft credit can also be associated directly with a Gift Transaction from its related list. The user selects a recipient, defines a partial amount or percentage of the transaction, and assigns a role such as Matched Donor. For a transaction-level soft credit, the credit can be up to 100 percent of the gift.","Gift Entry and Gift Entry Grid both support capturing soft credits with the rest of the gift information. Gift batch defaults can include soft credits, and processing creates multiple Gift Soft Credit records when an entry has multiple recipients. Fundraising summaries use soft-credit data for counts, dates, amounts, and combined hard-and-soft-credit metrics."],connections:[{"planet":"gift_transactions","desc":"Soft credits are linked to gift transactions"},{"planet":"constituents","desc":"Credits attributed to constituent accounts"},{"planet":"relationships","desc":"Relationships inform soft credit decisions"}]},
    {id:"matching-gift-tracking",name:"Matching Gift Tracking",icon:"\u{1F91D}",desc:"Matching Gift Tracking uses Gift Soft Credits to recognize a constituent’s matching-related influence on a donation. When creating a soft credit, users can assign the recipient a role such as Matched Donor. The credit can be entered as a Gift Commitment default or recorded for a specific Gift Transaction.",tags:["GiftTransaction"],docs:["To recognize a matched donor, select the soft-credit recipient and choose Matched Donor as the recipient role. Enter an amount or percentage to define the portion being credited. When added directly to a Gift Transaction, the soft credit can cover up to 100 percent of that transaction.","A matching-related credit entered in the Gift Default Soft Credits related list applies to every gift associated with the selected Gift Commitment. This approach supports commitments that generate multiple Gift Transactions while retaining the same credited recipient. Commitment-level default soft credits can be greater than 100 percent of the gift."],connections:[{"planet":"gift_transactions","desc":"Matching transactions link to original gifts"},{"planet":"constituents","desc":"Matching employers are organization accounts"}]},
    {id:"tribute-gifts",name:"Tribute & Memorial Gifts",icon:"\u{1F339}",desc:"Tribute and memorial gift context is represented conservatively in the documented soft-credit scope. Nonprofit Cloud donor portals can display tribute information alongside gift commitments, refunds, soft credits, and transactions. The documented workflow does not specify automatic soft-credit creation or attribution rules for tributes.",tags:["GiftSoftCredit"],docs:["Organizations can create an Experience Cloud donor portal that displays information related to tributes and soft credits with other fundraising records. Experience Cloud must be licensed, enabled, and configured before community users can access the site. Administrators should review permission sets to determine which Nonprofit Cloud objects are available to portal users."],connections:[{"planet":"gift_transactions","desc":"Tribute gifts are recorded as transactions with soft credits"},{"planet":"constituents","desc":"Honorees are constituent accounts"}]}
  ],
  dataFlow: ["Record the donor’s Gift Commitment or Gift Transaction.","Use constituent relationships and opportunity contact roles to identify parties that influenced the gift.","Select each credited constituent and assign the appropriate CreditType role.","Enter the soft-credit Amount or percentage on the commitment, transaction, or gift entry.","Process the gift to create transaction-level GiftSoftCredit records and update fundraising summaries."],
  connections: [{"planet":"gift_transactions","desc":"Soft credits on transactions"},{"planet":"constituents","desc":"Credits attributed to constituents"},{"planet":"relationships","desc":"Relationships inform attribution"},{"planet":"fundraising","desc":"Opportunity contact roles drive soft credits"}]
},

campaigns: {
  packages: ["nonprofitcloud"],
  name: "Campaigns & Outreach",
  icon: "\u{1F4E3}",
  color: "#3b82f6",
  description: "Campaigns & Outreach manages multichannel fundraising efforts in Nonprofit Cloud by connecting campaigns and Outreach Source Codes with donor engagement and Fundraising records. Campaigns source fundraising activity, provide default designations, and attribute opportunities, gift commitments, and gift transactions, while source codes capture the channel, message, and audience selected during gift entry. Household addressing and contact-point information support campaign communications, and campaigns can trigger Action Plans for related fundraising work. Data Processing Engine aggregates campaign metrics, and Agentforce provides campaign insights for performance review.",
  components: [
    {id:"campaign-management",name:"Campaign Management",icon:"\u{1F4CB}",desc:"Campaign Management organizes mass-market and multichannel fundraising efforts in Nonprofit Cloud. Campaign records capture core planning and financial details and connect outreach activity with gift commitments, gift transactions, and opportunities. Campaigns can also provide default gift designations for related incoming gifts and support interest tags for matching donors with outreach efforts. Fundraisers who create and manage campaigns require the Marketing User permission.",tags:["Campaign"],docs:["The Donor Engagement app provides access to campaigns, outreach source codes, gift commitments, reports, and other engagement data used for mass-market fundraising. Campaigns identify the fundraising efforts that generate commitments and transactions, while campaign dates, status, expected revenue, and cost information support planning and review. Fundraisers can also use interest tags on campaigns to associate outreach efforts with donor interests, preferences, and needs.","Campaigns participate in gift designation inheritance and allocation. Gift Default Designations associated with a campaign can automatically allocate related incoming gifts, and every gift must have at least one designation. For a one-time gift entry, default transaction designations are inherited from the campaign when available; otherwise, processing uses the organization-wide default designation.","Campaign work can use shared Nonprofit Cloud capabilities alongside fundraising records. Action Plans define required tasks for processes such as capital campaigns and other fundraising activities, while household addressing and contact-point information support campaign mailings and outreach. Data Processing Engine summarizes fundraising data, and Agentforce can provide campaign insights."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_outreach_source_code_campaigns.htm&type=5&language=en_US",connections:[{"planet":"fundraising","desc":"Campaigns source fundraising opportunities"},{"planet":"gift_transactions","desc":"Transactions attributed to campaigns"},{"planet":"gift_commitments","desc":"Commitments linked to campaigns"}]},
    {id:"outreach-source-codes",name:"Outreach Source Codes",icon:"\u{1F4F1}",desc:"Outreach Source Codes identify the outreach methods used with campaigns in Nonprofit Cloud. They provide more specific attribution for channels, messages, and audiences associated with a fundraising effort. Users can select a source code during gift entry, after which the related campaign is populated. Comparing results associated with source codes helps campaign managers determine which approaches are successful.",tags:["OutreachSourceCode"],docs:["An Outreach Source Code belongs to a campaign and records details about a particular outreach approach. Campaign managers use these records to distinguish activity by channel, message, or audience within a broader fundraising effort. Interest tags can also be used on Outreach Source Codes when that capability is enabled.","Create the applicable campaign and source-code records before entering gifts that must be attributed to them. In the Gift Entry window or Gift Entry Grid, users can select an outreach source code for a gift received in response to a solicitation. Selecting the source code automatically populates the campaign name, and fundraising validation confirms that the gift transaction's source code is valid for the selected campaign.","Outreach Source Codes can also be associated with gift commitment schedules and captured when recurring gift commitments change. The Gift Commitment Change Attribution Log records the campaign and outreach source code associated with a change. This history helps preserve the outreach context for upgrades, downgrades, and other commitment updates."],connections:[{"planet":"gift_transactions","desc":"Transactions attributed to specific source codes"},{"planet":"gift_entry","desc":"Source codes set during gift entry"}]},
    {id:"campaign-attribution",name:"Campaign Attribution",icon:"\u{1F3AF}",desc:"Campaign Attribution connects fundraising results to the campaigns and outreach methods that influenced them. Gift commitments can be linked to campaigns or opportunities, and gift transactions can be attributed to a commitment, campaign, and donor. Outreach Source Codes add solicitation-level context during gift entry while campaign defaults can determine gift designations. Recurring commitment changes can also retain campaign and source-code attribution.",tags:["Campaign","OutreachSourceCode"],docs:["Users can connect a one-time, multipayment, recurring, or in-kind gift commitment to a campaign or opportunity. A campaign can also be selected on a commitment schedule, and processing the schedule creates or updates the associated gift transactions. Gift transactions can therefore retain attribution to both the originating commitment and the relevant campaign.","Gift Entry supports campaign and Outreach Source Code values for both individual gifts and batches. When a gift was received in response to a solicitation, the user enters the source code and Nonprofit Cloud automatically populates its campaign. A campaign-and-source-code validation prevents a transaction from retaining a source code that isn't valid for the selected campaign.","Attribution also affects designation allocation. Default designations can come from a transaction's campaign, its commitment, the opportunity associated with that commitment, the commitment's campaign, or the organization-wide default, according to the documented inheritance order. If a recurring commitment upgrade is associated with an additional campaign, Gift Default Designations can attribute the commitment and its transactions across multiple campaigns according to the ratio in which they influenced the gift amount."],connections:[{"planet":"designations","desc":"Campaigns have default designations for sourced gifts"},{"planet":"gift_commitments","desc":"Commitment changes attributed to campaigns"}]},
    {id:"campaign-performance",name:"Campaign Performance",icon:"\u{1F4C8}",desc:"Campaign Performance uses summarized engagement, donation, and financial information to evaluate fundraising efforts in Nonprofit Cloud. Campaign pages can display rollups such as gift count, response rate, actual cost, and average gift amount. Data Processing Engine supports fundraising summaries, while reports and campaign-linked records provide additional analysis. Agentforce can supplement these records with campaign insights.",tags:["Campaign"],docs:["The Outreach Summary is an example of the Related Records Detail Display available on an Outreach Source Code or Campaign page. Administrators configure the component by selecting the related object, grouping the desired standard or custom fields, and optionally applying component-visibility filters. A Campaign Summary can include Start Date, Gift Count, Response Rate, Actual Cost in Campaign, and Average Gift Amount.","Data Processing Engine summarizes information about fundraising efforts and supports calculated fundraising rollups. Fundraising rollups can summarize campaign data alongside donor, household, and designation data. Campaign managers can use these summaries with campaign costs, expected revenue, attributed commitments, and attributed transactions to compare results and analyze campaign return on investment."],connections:[{"planet":"fundraising","desc":"Campaign data feeds fundraising strategy analytics"}]}
  ],
  dataFlow: ["Define the campaign, its financial details, default designations, audience, and required action plans.","Select household addressing and contact-point information for campaign outreach.","Create campaign-specific Outreach Source Codes for the channels, messages, and audiences used.","Apply a valid source code during gift entry to populate the campaign and source Fundraising records.","Link gift commitments and opportunities to campaigns, then attribute resulting gift transactions.","Run Data Processing Engine summaries and review campaign metrics, reports, and Agentforce insights."],
  connections: [{"planet":"fundraising","desc":"Campaigns source fundraising"},{"planet":"gift_transactions","desc":"Transactions attributed to campaigns"},{"planet":"gift_commitments","desc":"Commitments linked to campaigns"},{"planet":"gift_entry","desc":"Source codes applied during entry"},{"planet":"designations","desc":"Campaigns have default designations"},{"planet":"households","desc":"Campaign mailings use household addressing"},{"planet":"contact_points","desc":"Outreach uses contact information"},{"planet":"action_plans","desc":"Campaigns trigger action plans"},{"planet":"agentforce","desc":"AI provides campaign insights"},{"planet":"setup","desc":"DPE aggregates campaign metrics"}]
},

programs: {
  packages: ["nonprofitcloud"],
  name: "Program Management",
  icon: "\u{1F4DA}",
  color: "#22c55e",
  description: "Program Management in Nonprofit Cloud tracks mission-driven programs, their benefits, constituent participants, enrollments, cohorts, schedules, sessions, goals, and benefit delivery. It supports programs serving case participants, programs funded by grants, volunteer-supported delivery, and action plans that automate program steps. Program data can be linked to Outcome Management to evaluate effectiveness and can be summarized with Agentforce for stakeholder updates. Administrators enable and configure Program Management and its settings through Nonprofit Cloud Setup.",
  components: [
    {id:"program-records",name:"Programs",icon:"\u{1F3EB}",desc:"Programs represent the mission-driven services and initiatives that an organization delivers through Nonprofit Cloud. Program records organize benefits, participant enrollments, cohorts, schedules, and service-delivery activity so staff can make timely decisions from shared data. Programs can also be connected to case participants, outcome strategies, grant funding, volunteer support, action plan steps, and AI-generated program and benefit summaries.",tags:["Program"],docs:["Program Management provides a data model for tracking programs, benefits, and benefit disbursements in Nonprofit Cloud. A program record captures the offering that an organization operates, including its summary, status, and relevant dates. Staff can use Path on Program records to guide users through a defined business process and highlight important information at each stage.","Participants can be enrolled in a program and organized into program cohorts. Cohorts help staff manage groups when a program runs for a defined population or is offered multiple times. After service delivery is recorded, organizations can report on benefit distribution across different cohorts.","Programs can be linked to Outcome Management to measure whether services are being delivered as planned and whether they achieve intended outcomes. Program staff can also use Interaction Summaries for permanent notes, Data Processing Engine for program rollups, and Salesforce Channels for collaboration around long-running Program records. Where configured, Einstein Program and Benefits Summary uses Salesforce Program and Benefit data to draft progress summaries for stakeholders."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.prog_case_mgmt_prog_mgmt.htm&type=5&language=en_US",connections:[{"planet":"outcomes","desc":"Programs are measured by outcomes"},{"planet":"case_management","desc":"Programs serve case participants"},{"planet":"grantmaking","desc":"Grants fund programs"}]},
    {id:"benefits",name:"Benefits & Services",icon:"\u{1F381}",desc:"Benefits & Services define the classes, workshops, coaching, goods, or other assistance delivered through programs in Nonprofit Cloud. Benefit Types classify similar offerings, while units of measure specify how delivery is quantified, such as kits or hours. Benefits can be scheduled, assigned to participants, delivered in sessions, and included in care plan templates.",tags:["Benefit","BenefitType","UnitOfMeasure"],docs:["A Benefit record represents a service or good delivered through a program. Organizations can create Benefit Types to track similar benefits across programs and use a unit of measure to express the quantity delivered. For example, a distribution benefit can be measured in kits, while coaching and hands-on training can be measured in hours.","Recurring delivery is organized with Benefit Schedules and Benefit Sessions. Staff define a schedule on a benefit according to its recurrence and quantity, and sessions represent the scheduled occurrences where attendance can be tracked. Benefit sessions can also be displayed in Salesforce Calendar to help staff avoid scheduling conflicts.","When participants are added to a benefit schedule, Salesforce creates benefit assignments, benefit schedule assignments, and disbursements for them. Experience Cloud can allow assigned service providers to manage programs and benefits, add sessions, create disbursements, and track participant attendance. Volunteers can also track attendance, create disbursements, and add or remove participants from a session when the portal and permissions are configured."],connections:[{"planet":"outcomes","desc":"Benefit delivery drives outcome measurement"}]},
    {id:"enrollment",name:"Program Enrollment",icon:"\u{1F4DD}",desc:"Program Enrollment connects participants, who are constituents, to the programs they receive through Nonprofit Cloud. Enrollment records track application, participation, and completion information, while cohorts organize enrolled participants into defined groups. Beneficiaries can also use an appropriately configured Experience Cloud site to view and enroll in programs and benefits.",tags:["ProgramEnrollment","ProgramCohort","ProgramCohortMember"],docs:["Program staff create enrollments for participants who are represented in Salesforce as accounts or contacts. An enrollment identifies the participant and program and tracks the enrollment status and relevant dates. Path can guide users through the enrollment process by highlighting key fields and providing customized guidance at each step.","Program enrollments can be added to Program Cohorts, and cohort membership tracks the participant's place in the group. Cohorts are useful when a program serves a geographic group or runs several times during a year. Staff can then report on service delivery across cohorts after benefit disbursements are recorded.","Nonprofit Cloud can also use an active anonymous program enrollment for service recipients who aren't individually enrolled, as shown in the school kit distribution example. For known participants, scheduled benefits can create assignments and disbursements tied to their participation. Case Management and care plans can extend this participant record with intake, assessment, guided care, benefits, and goals."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.prog_case_mgmt_prog_mgmt_enroll_individuals.htm&type=5",connections:[{"planet":"constituents","desc":"Enrollees are constituent accounts"},{"planet":"case_management","desc":"Case referrals lead to program enrollment"}]},
    {id:"benefit-disbursement",name:"Benefit Disbursement",icon:"\u{1F4E4}",desc:"Benefit Disbursement records the quantity of a benefit delivered or expected to be delivered to a participant or anonymous recipient. Disbursements can be created from scheduled participation or entered for ad hoc service delivery, and their statuses support attendance tracking. These records provide the service-delivery data used to review participation and report program activity.",tags:["BenefitDisbursement","BenefitSchedule","BenefitSession","BenefitAssignment"],docs:["For ad hoc delivery, staff select the relevant benefit and record the recipients who received it. The school kit distribution example uses program enrollment recipients for enrolled children and an anonymous recipient type for visitors who aren't enrolled. Salesforce creates benefit assignments and disbursements for each benefit participant in that process.","For scheduled delivery, adding participants to a Benefit Schedule creates benefit assignments, schedule assignments, and disbursements. The disbursement reflects the quantity on the associated schedule and initially represents the participant's scheduled service. Each Benefit Session then provides a place to track attendance for that occurrence.","Staff update attendance to statuses such as Completed, Excused, or Absent from the session's Attendance tab. If a participant was excused or absent, staff set the disbursed quantity to zero because the participant didn't receive that session's benefit. Saving the attendance changes updates the corresponding participant disbursements."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.prog_case_mgmt_prog_mgmt_benefits_tracking.htm&type=5",connections:[{"planet":"constituents","desc":"Disbursements go to participant accounts"},{"planet":"outcomes","desc":"Disbursement data feeds outcome indicators"}]},
    {id:"goal-definitions",name:"Goal Definitions",icon:"\u{1F3C6}",desc:"Goal Definitions provide reusable goals that describe the results program participants are expected to pursue. Definitions can be arranged in a hierarchy, including top and intermediate goals, and can be associated with standardized care plan templates. When a care plan is assigned, its goals and benefits can be tailored to the participant's needs.",tags:["GoalDefinition"],docs:["Organizations can create a hierarchy of Goal Definition records to represent progressive participant objectives. In the job readiness example, the top goal is being hired for a job, supported by intermediate goals for communication improvement and technical proficiency. Each definition provides a named and described objective that can be organized under a parent goal.","Goal definitions can be added to a Care Plan Template through the Care Plan Template Goal related list. The same template can include program benefits through the Care Plan Template Benefit related list. Staff then assign the care plan to program participants to combine relevant benefits and goals in a personalized plan."],connections:[{"planet":"outcomes","desc":"Goals connect to outcome definitions and indicators"},{"planet":"case_management","desc":"Care plans reference goal definitions"}]}
  ],
  dataFlow: ["Configure Program Management settings in Nonprofit Cloud Setup.","Create grant-funded programs, benefits, benefit types, units of measure, schedules, sessions, and goal definitions.","Enroll constituent and case participants, organize them into cohorts, and automate program steps with action plans.","Assign scheduled or ad hoc benefits and record attendance and benefit disbursements.","Measure programs through linked outcomes and coordinate volunteer support for service delivery.","Summarize program benefits with Agentforce and report participant, cohort, and delivery activity."],
  connections: [{"planet":"constituents","desc":"Participants are constituents"},{"planet":"outcomes","desc":"Programs measured by outcomes"},{"planet":"case_management","desc":"Programs serve case participants"},{"planet":"grantmaking","desc":"Grants fund programs"},{"planet":"volunteers","desc":"Volunteers support programs"},{"planet":"action_plans","desc":"Action plans automate program steps"},{"planet":"setup","desc":"Program settings in setup"},{"planet":"agentforce","desc":"AI summarizes program benefits"}]
},

case_management: {
  packages: ["nonprofitcloud"],
  name: "Case Management",
  icon: "\u{1F4C2}",
  color: "#0ea5e9",
  description: "Case Management in Nonprofit Cloud equips case managers, social workers, and program staff with tools for referral intake, assessment, case follow-up, and personalized care planning. Referrals involving constituents can become cases, while discovery activities and reusable care plan templates help staff organize participant-specific benefits and goals that can lead to program enrollment. Interaction Summaries preserve detailed, searchable notes and can provide grounding data for AI-generated notes summaries. Case outcomes can be tracked through Outcome Management, while setup, permissions, sharing, and other access controls protect sensitive case information.",
  components: [
    {id:"case-referral-intake",name:"Case Referral Intake",icon:"\u{1F4E5}",desc:"Case Referral Intake supports inbound and outbound participant referrals in Nonprofit Cloud. Guided flows streamline intake for staff and program participants, and referrals can be converted into cases for assessment and follow-up. Case records connect the resulting work to constituents and capture operational details such as status, priority, origin, and description.",tags:["Case","CaseReferral"],docs:["Case Referral Intake gives case managers and program staff a structured way to process referral requests. It supports referrals into and out of the organization and records the referral type, referring organization, reason, and status. A referral can be associated with a case so that staff can continue assessment and follow-up in a managed case process.","Administrators enable and configure Case Referrals from Nonprofit Cloud setup, and users need the Case Referral permission set to perform the related setup. Guided flows can streamline the intake experience for staff and participants. Because cases contain constituent and service information, organizations must configure appropriate object, field, and record access."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.prog_case_mgmt_case_referral_intake.htm&type=5",connections:[{"planet":"constituents","desc":"Referrals involve constituent records"},{"planet":"programs","desc":"Referrals lead to program enrollment"}]},
    {id:"care-plans",name:"Care Plans",icon:"\u{1F4CB}",desc:"Care Plans in Nonprofit Cloud provide personalized plans that help program participants address challenges and pursue life goals. Staff can start with standardized Care Plan Templates and customize each plan for a participant’s needs. Template benefits and goals provide recommended elements that can be carried into plans associated with participants and cases.",tags:["CarePlan","CarePlanTemplate","CarePlanTemplateBenefit","CarePlanTemplateGoal"],docs:["Care Plans provide a structured way to create, manage, and share individualized plans for program participants. Each plan can identify the participant account and related case, track status, and define start and end dates. Plans can support the transition from case work into program participation and services.","Organizations define reusable Care Plan Templates and mark the appropriate templates as active. Care Plan Template Benefit records associate recommended benefits and quantities with a template, while Care Plan Template Goal records associate goal definitions and target days. Staff can start from these standardized elements and tailor the resulting care plan to the participant.","Administrators enable and configure Care Plans in Nonprofit Cloud setup, and the Care Plans Access permission set is required for setup. CarePlan supports Salesforce Path, which can guide users through process stages, highlight important fields, and provide customized guidance. Access to care plans and related case information must be governed through the organization’s security configuration."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.prog_case_mgmt_care_plans.htm&type=5",connections:[{"planet":"programs","desc":"Care plans assign participants to program benefits"},{"planet":"outcomes","desc":"Care plan goals link to outcome measurement"}]},
    {id:"assessments",name:"Assessments & Discovery",icon:"\u{1F50D}",desc:"Assessments & Discovery supports the collection and evaluation of participant information during case intake and ongoing service delivery. Discovery Framework records define reusable assessment structures and scoring methods, while Assessment Task records track participant-specific assessment work. Completed assessments can inform case follow-up, care planning, program enrollment, and outcome tracking.",tags:["AssessmentTask","DiscoveryFramework"],docs:["Case Management equips staff with assessment tools as part of intake and guided care planning. A Discovery Framework identifies the assessment definition, description, active status, and scoring method. This structure supports consistent discovery of information needed to understand a participant’s circumstances.","Assessment Task records associate assessment work with a participant account and Discovery Framework. Staff can track the task’s status, score, and completion date as assessment work progresses. Assessment findings can then inform case decisions and the personalized benefits and goals included in a care plan."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.discovery_framework_prerequisites.htm&language=en_US",connections:[{"planet":"constituents","desc":"Assessments are completed for participant accounts"}]},
    {id:"interaction-summaries",name:"Interaction Summaries",icon:"\u{1F4DD}",desc:"Interaction Summaries capture permanent, detailed notes from meetings and conversations with participants, caseworkers, advisors, partners, and other stakeholders. Staff can record the interaction type and date, notes, next steps, and confidentiality status, then search for previous interactions. Nonprofit Cloud generative AI can summarize related notes to help case managers review participant history and identify actions that remain incomplete.",tags:["InteractionSummary"],docs:["Interaction Summaries provide structured, searchable records of stakeholder interactions. Caseworkers can preserve detailed notes, record next steps, and quickly locate information from earlier conversations. Confidentiality settings help protect sensitive notes while keeping relevant information available to authorized users.","Interaction Summaries are a Nonprofit Cloud prerequisite that administrators enable in setup. When enabling the feature, Salesforce directs administrators to turn on Role Hierarchy–Based Sharing for Interaction Summary and Interactions, along with the Enhanced Interaction Note Interface. These settings support controlled access and the note-taking experience for caseworkers and other users.","Einstein Notes Summary uses Salesforce data from Account, Interaction, and Interaction Summary records to generate a concise view of constituent or participant notes. It can help case managers prepare for an interaction and identify actions or tasks recorded in notes that have not been completed. Blank grounding fields can lead to incomplete output, so organizations should maintain complete interaction and summary data."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.fsc_enable_config_interaction_summaries.htm&type=5&language=en_US",connections:[{"planet":"constituents","desc":"Interaction notes linked to constituent accounts"},{"planet":"agentforce","desc":"Einstein summarizes interaction notes"}]}
  ],
  dataFlow: ["Enable case referrals, care plans, assessments, and interaction summaries in setup, then assign permissions and access controls.","Receive an inbound or outbound constituent referral and convert it into a case for assessment and follow-up.","Complete discovery and assessment tasks, and use action plans to automate required case steps.","Create a template-based care plan and use the case to guide benefits, goals, and program enrollment.","Record confidential interaction notes and use Agentforce to summarize participant history and outstanding actions.","Track case outcomes and evaluate participant progress through connected outcome management records."],
  connections: [{"planet":"constituents","desc":"Cases involve constituents"},{"planet":"programs","desc":"Cases lead to program enrollment"},{"planet":"outcomes","desc":"Case outcomes tracked"},{"planet":"agentforce","desc":"AI summarizes notes"},{"planet":"action_plans","desc":"Action plans automate case steps"},{"planet":"security","desc":"Case data requires access controls"},{"planet":"setup","desc":"Case settings in setup"}]
},

outcomes: {
  packages: ["nonprofitcloud"],
  name: "Outcome Management",
  icon: "\u{1F4C8}",
  color: "#84cc16",
  description: "Outcome Management in Nonprofit Cloud defines an impact strategy or theory of change, collects measurement data, tracks progress, and evaluates program effectiveness. Outcome Definitions describe intended results, Indicators establish measures and targets, and Indicator Results record measured values over time. The strategy connects outcomes to programs, benefits, and case-related work, while collected data supports reporting to communities, boards, donors, and grant stakeholders. Impact information also supports grant reporting and donor reporting by fundraising designation.",
  components: [
    {id:"outcome-definitions",name:"Outcome Definitions",icon:"\u{1F3AF}",desc:"Outcome Definitions represent the intended results in an organization's impact strategy or theory of change. They provide a structured way to describe outcomes for a target population and relate outcomes through a parent outcome. In Nonprofit Cloud, the outcome strategy can be linked to programs and benefits so organizations can evaluate whether their work achieves its intended results.",tags:["OutcomeDefinition"],docs:["Use Outcome Definitions to express the results that an organization intends to achieve through its programs and services. Together, these definitions form part of an impact strategy or theory of change. They establish the outcomes against which collected data and program effectiveness can be evaluated.","Record a description and target population for each outcome, and use ParentOutcomeId when the outcome belongs under another outcome. IsActive identifies whether the definition is currently active. Link the resulting outcome strategy to programs and benefits in Nonprofit Cloud to connect intended impact with service delivery."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.outcome_management.htm&type=5",connections:[{"planet":"programs","desc":"Outcomes link to the programs that drive them"},{"planet":"grantmaking","desc":"Outcomes demonstrate impact to grant funders"}]},
    {id:"indicators",name:"Indicators",icon:"\u{1F4CF}",desc:"Indicators specify how progress toward an Outcome Definition is measured. Each indicator can identify its data type, collection frequency, target value, and baseline value. These measures help organizations track program performance and determine whether programs and case-related work are contributing to intended outcomes.",tags:["Indicator"],docs:["Create Indicators to define the measures used to track progress toward intended outcomes. Associate each indicator with an Outcome Definition so that collected values can be evaluated in the context of the organization's impact strategy. Indicators support tracking both whether programs are delivered as planned and whether the work achieves its intended outcomes.","Configure the indicator's DataType and CollectionFrequency to describe the expected measurement and collection approach. BaselineValue provides a starting point, while TargetValue records the result the organization intends to reach. These values provide context for evaluating subsequent Indicator Results."],connections:[{"planet":"programs","desc":"Indicators measure program activities and benefits"}]},
    {id:"indicator-results",name:"Indicator Results",icon:"\u{1F4CA}",desc:"Indicator Results capture collected measurements for an Indicator over time. A result records the measured value, measurement date, and collection context needed to interpret the data point. Nonprofit Cloud can use indicator result information when tracking program effectiveness and reporting on grant performance.",tags:["IndicatorResult"],docs:["Create Indicator Results as outcome data is collected. Associate each result with its Indicator and record the ResultValue and MeasurementDate. CollectionContext can preserve relevant information about the circumstances in which the measurement was obtained.","Use the accumulated results to track progress and evaluate whether programs and case-related services are achieving intended outcomes. Indicator result data can also contribute to grant reporting; for example, the Einstein Funding Award Summary uses Indicator Results together with funding award, requirement, performance-period, and disbursement data. Populated result data helps provide a more complete account of grant milestones and performance."],connections:[{"planet":"programs","desc":"Results are collected from program activities"}]},
    {id:"impact-reporting",name:"Impact Reporting",icon:"\u{1F4D1}",desc:"Impact Reporting uses collected outcome data to communicate program progress and effectiveness. Reports can connect outcomes with programs and benefits and can be shared with communities served, boards, donors, and other stakeholders. Outcome information also supports grant reporting, while synchronized fundraising designation data supports impact reporting to donors by designation.",tags:["OutcomeDefinition","Indicator"],docs:["Use the data collected through Outcome Management to create reports on outcomes. Reports can show the programs being run to achieve intended outcomes, whether those programs are being delivered as planned, and whether the work is producing the intended results. Organizations can share these reports with the communities they serve, their boards, donors, and other relevant stakeholders.","Outcome data can support reporting on grants because funding award summaries can draw on Indicator Results and Indicator Performance Period information alongside award requirements and disbursements. Fundraising data also supports impact reporting by designation: allocation data is synchronized across gift entry, gift commitment, gift transaction, and gift designation records. The gift transaction designation serves as the source of truth for updating gift designation rollups used in donor impact reporting."],connections:[{"planet":"grantmaking","desc":"Impact reports support grant reporting requirements"},{"planet":"designations","desc":"Designation-level impact reporting for donors"}]}
  ],
  dataFlow: ["Define intended outcomes and organize them within the impact strategy or theory of change.","Link the outcome strategy to programs, benefits, and case-related work.","Configure indicators with baseline values, target values, and collection frequencies.","Collect dated indicator results with the relevant measurement context.","Evaluate program and case outcomes against the defined measures.","Report impact for stakeholders, grant reporting, and fundraising designations."],
  connections: [{"planet":"programs","desc":"Programs measured by outcomes"},{"planet":"case_management","desc":"Case outcomes tracked"},{"planet":"grantmaking","desc":"Outcomes support grant reporting"},{"planet":"designations","desc":"Impact reporting by designation"}]
},

volunteers: {
  packages: ["nonprofitcloud"],
  name: "Volunteer Management",
  icon: "\u{1F9D1}\u{200D}\u{1F91D}\u{200D}\u{1F9D1}",
  color: "#eab308",
  description: "Volunteer Management in Nonprofit Cloud streamlines the volunteer lifecycle from opportunity planning and recruitment through scheduling, hour tracking, and reporting. Volunteer Initiatives organize work that supports programs, while Positions, Job Positions, qualifications, shifts, and assignments define staffing requirements and participation. Volunteers are managed as constituents through Person Accounts, and matching uses competency, availability, and location information to identify suitable candidates. Setup options, Action Plans, Agentforce for Nonprofit Cloud, and Experience Cloud portals provide administration, onboarding automation, assisted matching, and volunteer self-service.",
  components: [
    {id:"volunteer-initiatives",name:"Volunteer Initiatives",icon:"\u{1F3C1}",desc:"Volunteer Initiatives organize the volunteer work that helps an organization accomplish its goals and support its programs. Each initiative can specify dates, volunteer and hour targets, status, and a parent initiative. Job positions and shifts define how the initiative is staffed. Published initiatives can be made available through an Experience Cloud site.",tags:["VolunteerInitiative"],docs:["Create a volunteer initiative to represent a project or other organized volunteer effort. Record its applicable details, including start and end dates, the number of volunteers needed, and the total volunteer hours to be filled. An initiative can also be associated with a parent initiative when it is part of a larger effort.","Staff an initiative by creating related job positions and the shifts that volunteers can fill. Stage Management can track an initiative from upcoming and in-progress stages through completion, including internal approvals. Organizations can also configure an approval process for volunteer initiatives.","Select Published when an initiative is ready to be made available through an Experience Cloud site. Volunteers can then discover the related opportunities through a configured volunteer portal. Initiative, job position, and shift information also provides the context used to match and assign volunteers."],connections:[{"planet":"programs","desc":"Volunteer initiatives support program delivery"},{"planet":"action_plans","desc":"Action plans automate initiative setup tasks"}]},
    {id:"positions-job-positions",name:"Positions & Job Positions",icon:"\u{1F464}",desc:"Positions define reusable functional roles characterized by specific duties, responsibilities, skills, and qualifications. Job Positions adapt those general roles to a particular Volunteer Initiative and can include dates, status, manager, location, and initiative-specific requirements. A Position can be used across multiple initiatives, while each Job Position represents a more specific staffing need. Action Plans and Stage Management can support the development, review, approval, and fulfillment of these records.",tags:["Position","JobPosition"],docs:["Create Positions for generic types of volunteer work that can be reused across initiatives. A Position can describe the role and identify the skills or qualifications required to hold it. If internal review is required, the Position can participate in the approval process configured for Volunteer Management.","Create a Job Position after establishing the Volunteer Initiative that it supports. The Job Position can be associated with a general Position and related to a specific initiative, making it a customized role for that effort. From the Job Position page, volunteer managers can create a shift schedule, find volunteers, or assign volunteers.","Position Qualifications define requirements that apply across all Job Positions related to a Position, while Job Position Qualifications add requirements for one specific Job Position. Qualifications can reference a Competency or an Examination, although volunteer matching evaluates competencies rather than examinations. Qualification levels must be configured on the relevant qualification records for level-based matching."],connections:[{"planet":"programs","desc":"Positions align with program service delivery needs"}]},
    {id:"shifts-assignments",name:"Shifts & Assignments",icon:"\u{1F4C5}",desc:"Job Position Shifts represent specific periods of volunteer work associated with a Job Position or recurrence schedule. Shift capacity controls how many volunteers can be assigned, supporting coverage planning for Volunteer Initiatives. Job Position Assignments connect volunteers to positions or specific shifts and track assignment status and hours. Volunteer managers can use flexible assignment options to schedule individuals and align their work with organizational goals.",tags:["JobPositionShift","JobPositionAssignment"],docs:["Create an individual shift from the Job Position Shifts page, or create multiple one-time or recurring shifts from a Job Position. Each scheduled shift includes a start time, end time, and maximum number of volunteers. Recurring schedules can generate shifts according to the configured recurrence and ending criteria.","Assign volunteers from a Job Position Shift by selecting an assignment status, choosing the shift, and selecting one or more volunteer Person Accounts. If no shift is selected, the assignment applies to the Job Position without creating a shift-specific assignment. Assignments configured to count toward capacity reduce the remaining availability for the shift.","Use Job Position Assignments to manage volunteer scheduling and record hours. Stage Management can track shifts as they move toward upcoming or completed stages and can track assignments that require approval or hour approval. Assignment records provide the basis for monitoring coverage, volunteer participation, and reported hours."],connections:[{"planet":"constituents","desc":"Volunteers assigned to shifts are constituent accounts"}]},
    {id:"volunteer-matching",name:"Volunteer Matching",icon:"\u{1F50D}",desc:"Volunteer Matching searches for suitable volunteers based on qualifications, shift or date-and-time criteria, and location. Volunteers are represented as Person Accounts with related competencies and location availability. Qualification matching is inclusive, so a volunteer whose qualification level meets or exceeds the required level is considered a match. Agentforce for Nonprofit Cloud can also identify unfilled shifts and find suitable volunteers.",tags:["PersonCompetency","PersonExamination","PersonLocationAvailability","Competency","Examination"],docs:["Configure volunteer details before running a search by creating Person Accounts and adding their location availability and competencies. A Person Competency must have a Qualification Level to appear as a match because matching evaluates that integer rather than the Proficiency Level value. Examination results can document licenses or permits, but examinations aren't evaluated by volunteer matching.","Start a search by selecting a Volunteer Initiative and Job Position. Choose which Position Qualifications and Job Position Qualifications are required, then optionally filter by a shift or date-and-time range and the Job Position location. Matching criteria can be omitted individually, but a search with no selected criteria returns no volunteers.","Search results identify volunteers who best fit the selected criteria and indicate related assignments or shifts when the volunteer is already signed up. Results can be exported to a CSV file saved on the Job Position record for follow-up. The Shift Capacity and Coverage subagent in Agentforce for Nonprofit Cloud can identify shifts with insufficient sign-ups and match volunteers to shifts."],connections:[{"planet":"constituents","desc":"Matching evaluates volunteer profiles"}]},
    {id:"volunteer-portal",name:"Volunteer Portal",icon:"\u{1F310}",desc:"The Volunteer Portal uses Experience Cloud to provide self-service access to volunteer opportunities and tasks. Organizations can publish opportunities so volunteers can browse, search, and sign up for them. A configured portal can also support registration, onboarding, training, document uploads, and volunteer hour tracking. Access is controlled through the applicable Experience Cloud licenses and Volunteer Management permission sets.",tags:["VolunteerInitiative"],docs:["Enable Digital Experiences and create an Experience Cloud site to establish a volunteer portal. Publish Volunteer Initiatives that should be available to portal users. Volunteers can use the site to view and sign up for available opportunities.","A portal can provide a place for volunteers to register, complete onboarding, attend training or continuing education, upload documentation, and track volunteered hours. Assign the Manage Volunteer Work in Experience Cloud permission set to authenticated portal users who need Volunteer Management access. Guest access requires the Volunteer Management in Experience Cloud Guest Access permission set, which can be customized with a muting permission set."],connections:[{"planet":"constituents","desc":"Portal creates or links to volunteer accounts"},{"planet":"agentforce","desc":"AI agent assists volunteer portal users"}]}
  ],
  dataFlow: ["Enable Volunteer Management in Setup, assign permissions, and configure locations, operating hours, and assignment defaults.","Create volunteer constituents as Person Accounts and record their competencies, examinations, and location availability.","Define Volunteer Initiatives that support programs, then add reusable Positions, specific Job Positions, qualifications, and shifts.","Apply Action Plans to automate volunteer onboarding tasks and publish eligible opportunities to the Experience Cloud portal.","Match volunteers by qualifications, availability, and location, using Agentforce for Nonprofit Cloud when appropriate, and create assignments.","Track assignment status and actual hours, monitor shift coverage, and report volunteer metrics."],
  connections: [{"planet":"constituents","desc":"Volunteers are constituents"},{"planet":"programs","desc":"Volunteers support programs"},{"planet":"action_plans","desc":"Action plans automate volunteer onboarding"},{"planet":"agentforce","desc":"AI assists volunteer matching"},{"planet":"setup","desc":"Volunteer settings in setup"}]
},

grantmaking: {
  packages: ["nonprofitcloud"],
  name: "Grantmaking",
  icon: "\u{1F4B5}",
  color: "#f43f5e",
  description: "Grantmaking is an optional Nonprofit Cloud capability for planning, managing, delivering, and measuring outbound grants of currency or goods. It tracks funding opportunities, applicant organization accounts, applications, reviews, budgets, awards, and grantee collaboration through Experience Cloud. Approved grants can fund programs and use Outcome Management to measure progress and results. Organization relationships inform grant decisions, action plans support review workflows, Agentforce summarizes applications, and grants received by the organization use the inbound fundraising pipeline.",
  components: [
    {id:"funding-opportunities",name:"Funding Opportunities",icon:"\u{1F4E2}",desc:"Funding Opportunities define available outbound funding and the application details prospective applicants need. Nonprofit Cloud uses them to provide a unified view of funding programs across planning, delivery, and evaluation. Grant seekers can discover published opportunities through an Experience Cloud portal and use the stated description, deadline, eligibility criteria, and funding amount to determine whether to apply.",tags:["FundingOpportunity"],docs:["Funding Opportunities help grantmakers plan and communicate available grants of currency or goods. Each opportunity can capture its name, description, available funding amount, application deadline, eligibility criteria, and status. The opportunity provides context for the applications, reviews, budgets, awards, and evaluation activities that follow.","When Nonprofit Cloud is used with Experience Cloud, grant seekers can learn about funding opportunities through an online portal. The IsPublished value can distinguish opportunities intended for publication from those not published. Applicants can then submit applications, budgets, and supporting documents for the selected opportunity."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.grmk_grantmaking.htm&type=5",connections:[{"planet":"programs","desc":"Funding opportunities support specific programs"},{"planet":"outcomes","desc":"Grant opportunities specify outcome requirements"}]},
    {id:"grant-applications",name:"Grant Applications",icon:"\u{1F4DD}",desc:"Grant Applications capture an applicant organization’s request for funding, including the requested amount and project narrative. Nonprofit Cloud supports application review and approval workflows, with ApplicationReview records storing reviewer scores, comments, and recommendations. Agentforce generative AI can create a streamlined board version of an application from Salesforce application, review, and funding opportunity data.",tags:["GrantApplication","ApplicationReview"],docs:["A GrantApplication connects a funding request to a FundingOpportunity and an applicant organization account. It records the requested amount, project narrative, submission date, and application status. Grantmakers can also track the organizations and people involved throughout the application process, with organization relationships providing additional context for grant decisions.","ApplicationReview records support structured evaluation by associating an application with a reviewer and capturing a score, comments, and recommendation. Action plans can support the review workflow, while Nonprofit Cloud manages the related approval process for applications and budgets. These records give program officers and decision-makers a consistent basis for reviewing requests.","Agentforce generative AI can produce a distilled board version of a grant application for final review. The summary is grounded in application, ApplicationReview, and FundingOpportunity data in Salesforce, and populated fields produce more complete output. Administrators enable the generative AI settings and add the Einstein Summary component with the applicable record-summary prompt template to the application page."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.grmk_get_started_with_grantmaking.htm&language=en_US",connections:[{"planet":"constituents","desc":"Applicants are organization accounts"},{"planet":"agentforce","desc":"AI generates board-ready summaries of applications"}]},
    {id:"grant-budgets",name:"Grant Budgets & Awards",icon:"\u{1F4B0}",desc:"Grant Budgets & Awards support the approval, delivery, and ongoing evaluation of outbound funding. Budget records organize requested and approved amounts by category and retain the applicant’s justification. FundingAward records track approved grants, recipients, award amounts and dates, status, and disbursed amounts, while related requirements, disbursements, and outcome information help officers assess grant health.",tags:["Budget","FundingAward"],docs:["Nonprofit Cloud supports the review and approval of budgets submitted with grant applications. Budget records can identify a category, requested amount, approved amount, and justification for the request. This structure lets grantmakers preserve both the applicant’s proposal and the amount ultimately approved.","A FundingAward represents an approved grant and associates it with the application and recipient account. Grantmakers can track the award amount, decision or award timing, status, requirements, and funding disbursements as the grant is delivered. Awards can fund programs, and Outcome Management can measure progress and report whether the funded work is achieving its intended results.","The generative AI funding award summary helps program officers evaluate whether a grant is meeting milestones and fulfilling requirements. It uses Salesforce data from the award, award requirements, funding disbursements, indicator performance periods, indicator results, and funding opportunity. Officers can use the resulting summary when considering engagement, additional disbursements, or future funding."],connections:[{"planet":"fundraising","desc":"Inbound grants use the fundraising pipeline"},{"planet":"programs","desc":"Awards fund specific program activities"}]},
    {id:"grantee-portal",name:"Grantee Portal",icon:"\u{1F310}",desc:"The Grantee Portal uses an Experience Cloud site template to support online communication and collaboration between grantmakers, applicants, and grantees. Grant seekers can discover funding opportunities, apply for funding, submit budgets, and upload supporting documents. The portal extends Nonprofit Cloud grantmaking processes to external users while keeping opportunity and application information connected to Salesforce records.",tags:["FundingOpportunity","GrantApplication"],docs:["Nonprofit Cloud provides a site template for Experience Cloud that helps organizations create an online grantee portal. The portal gives grant seekers a place to learn about available funding opportunities and submit applications. It also supports budget submission and the upload of documents required for the funding request.","Organizations must have the necessary Experience Cloud license and enable and configure Experience Cloud in their Salesforce org. Administrators should review permission sets to determine which Nonprofit Cloud objects are available to community users. Experience Builder is used to manage the site’s pages and their properties."],connections:[{"planet":"outcomes","desc":"Grantees report outcomes through the portal"}]}
  ],
  dataFlow: ["Create a FundingOpportunity with its funding amount, application details, eligibility criteria, deadline, status, and publication setting.","Publish eligible opportunities in the Experience Cloud grantee portal for prospective applicants to discover.","Capture each request as a GrantApplication tied to an organization account, using organization relationships for context and Agentforce to summarize application information.","Collect budgets and supporting documents, then coordinate ApplicationReview and approval work with action plans.","Approve the budget, create the FundingAward, track disbursements, and connect funded work to programs.","Measure grant progress through outcomes, and manage grants received by the organization through the inbound fundraising pipeline."],
  connections: [{"planet":"fundraising","desc":"Inbound grants use the fundraising pipeline"},{"planet":"programs","desc":"Grants fund programs"},{"planet":"outcomes","desc":"Grants measured by outcomes"},{"planet":"constituents","desc":"Applicants are organization accounts"},{"planet":"agentforce","desc":"AI summarizes grant applications"},{"planet":"relationships","desc":"Organization relationships inform grants"},{"planet":"action_plans","desc":"Action plans support grant review workflows"}]
},

agentforce: {
  packages: ["nonprofitcloud"],
  name: "Agentforce & Einstein AI",
  icon: "\u{1F916}",
  color: "#6366f1",
  description: "Agentforce & Einstein AI brings generative and conversational AI capabilities to Nonprofit Cloud across fundraising, program and case management, grantmaking, and volunteer management. Einstein capabilities generate draft gift proposals and summarize programs, interaction notes, funding awards, and grant applications. Agentforce agents support donor research and service, campaign insights, gift entry, participant operations, and volunteer matching through configurable subagents. Administrators enable the required AI settings, configure components or agents, test the experience, and assign access to users.",
  components: [
    {id:"gift-proposals",name:"AI Gift Proposals",icon:"\u{1F4DD}",desc:"AI Gift Proposals brings generative and conversational AI to major-gift fundraising in Nonprofit Cloud. It uses data in the Salesforce org to draft personalized gift proposals that communicate the organization’s mission, tone, and the potential impact of a donor’s contribution. The capability helps major gift officers reduce the time and effort required to prepare proposals for high-net-worth donors.",tags:[],docs:["AI Gift Proposals uses Einstein Copilot and the Copilot Actions: Fundraising Gift Proposals capability to produce draft gift proposals. Major gift officers can ask Einstein Copilot to create a proposal grounded in their organization’s Salesforce data. The generated draft is intended to help officers develop compelling, personalized solicitations.","The capability is available in Lightning Experience with supported Nonprofit Cloud editions and an eligible Einstein add-on. The documented Einstein Copilot capability is a beta service, so use is optional and subject to the applicable Beta Services Terms. Organizations should review generated drafts before using them in donor communications."],connections:[{"planet":"fundraising","desc":"Gift proposals support major gift solicitations"},{"planet":"constituents","desc":"Proposals personalized based on donor data"}]},
    {id:"ai-summaries",name:"Einstein Summaries",icon:"\u{1F4CB}",desc:"Einstein Summaries uses Salesforce data to draft program and benefit summaries, notes summaries, funding award summaries, and streamlined grant applications for board review. These summaries help program managers, case managers, major gift officers, and grantmaking program officers absorb record information and prepare stakeholder updates. The generated content can be copied for use in documents or regenerated to produce another version.",tags:[],docs:["Einstein Program and Benefits Summary drafts updates about a program and its benefits for internal and external stakeholders. Einstein Notes Summary condenses information about constituents, participants, or grantees and can surface actions or tasks recorded in notes that remain incomplete. The grantmaking capabilities summarize funding awards to help officers assess milestones and requirements, and create distilled versions of grant applications for board review.","Administrators first set up the applicable Nonprofit Cloud features and Einstein generative AI, enable Nonprofit Cloud Generative AI Settings and Context Definitions, and then add the Einstein Summary component to Lightning record pages. Each component is configured with the Record Summary prompt template type and the appropriate prompt template. Supported placements include program pages, individual account pages, individual application pages, and funding award pages.","The summaries are grounded in relevant Salesforce records, including programs and benefits, accounts and interaction summaries, grant applications and reviews, and funding awards with related requirements, disbursements, and indicator data. A generation can use up to 100 related records as grounding data. Blank fields aren’t omitted during response generation and can lead to incomplete output, so organizations should populate the relevant source data before generating a summary.","Users open the applicable record and generate the summary from its Einstein Summary pane. They can copy the result into another document or select Generate to receive a different version. The documented summary capabilities are pilot or beta services, consume Einstein Requests, and are subject to the applicable terms."],docUrl:"https://help.salesforce.com/s/articleview?id=ai.generative_ai.htm&type=5",connections:[{"planet":"programs","desc":"AI summarizes program benefits"},{"planet":"case_management","desc":"AI summarizes interaction notes"},{"planet":"grantmaking","desc":"AI creates board-ready grant summaries"}]},
    {id:"volunteer-agent",name:"Volunteer AI Agent",icon:"\u{1F9D1}\u{200D}\u{1F4BB}",desc:"Volunteer AI Agent helps Nonprofit Cloud teams manage volunteer initiatives and shifts with less administrative effort. Its Shift Capacity & Coverage subagent identifies unfilled shifts and finds suitable volunteers to fill them. This assistance supports volunteer matching and can help organizations improve volunteer engagement.",tags:[],docs:["The Volunteer Management Agent supports work involving volunteer shifts and initiatives. In Agent Builder, teams can access the Shift Capacity & Coverage subagent to identify shifts that still need coverage. The subagent then helps find the most suitable volunteers for those shifts.","Before creating the agent, administrators set up Nonprofit Cloud and Einstein generative AI, turn on Agentforce, and enable Agentforce Employee Agents and Einstein Generative AI in Nonprofit Cloud AI Settings. They create the agent from the required template, define its system messages and tone, and add the applicable subagents. The agent must be tested, activated, and assigned to users before it is available to the team."],connections:[{"planet":"volunteers","desc":"AI agent assists volunteer operations"}]},
    {id:"fundraising-agent",name:"Fundraising AI Agent",icon:"\u{1F4B0}",desc:"Fundraising AI Agent applies Agentforce to fundraising initiatives and donor-management workflows in Nonprofit Cloud. Available subagents support philanthropic research and donor requests involving recurring gift commitments. The agent also assists fundraising work involving campaign insights and gift entry, helping teams perform related tasks more efficiently.",tags:[],docs:["Philanthropic Research subagents help fundraising teams optimize donor research and engagement. Teams can use the resulting insights to tailor outreach, develop personalized engagement strategies, and build deeper donor relationships. This research support complements campaign insights used to guide fundraising activity.","The Donor Support Agent uses the Manage Gift Commitments subagent to help donors manage existing gift commitments with recurring schedules through an Experience Cloud site. Supported requests include pausing, resuming, or closing a commitment and updating its amount. Agentforce also assists gift-entry work as part of the connected fundraising workflow.","Administrators create a Nonprofit Cloud agent with the Agentforce Employee Agent template or the template required for the specific agent. They can customize welcome and error messages, set the agent’s tone through language settings, and add the required subagents. After testing the agent for reliable behavior, administrators activate it and assign it to users."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_philanthropic_research_topics_in_agentforce.htm&language=en_US",connections:[{"planet":"campaigns","desc":"AI provides campaign performance insights"},{"planet":"gift_entry","desc":"AI assists with gift data entry"}]}
  ],
  dataFlow: ["Enable Einstein generative AI, Agentforce, and the required Nonprofit Cloud features.","Configure summary components, agent templates, messages, permissions, and subagents.","Ground requests in Salesforce fundraising, program, case, grantmaking, volunteer, campaign, and gift-entry data.","Generate gift proposals, program and note summaries, grant summaries, and board-ready application versions.","Use agents to research donors, surface campaign insights, assist gift entry, and match volunteers to uncovered shifts.","Review generated results, regenerate or copy summaries as needed, and complete the related business workflow."],
  connections: [{"planet":"fundraising","desc":"AI generates gift proposals"},{"planet":"programs","desc":"AI summarizes programs"},{"planet":"case_management","desc":"AI summarizes notes"},{"planet":"grantmaking","desc":"AI summarizes grants"},{"planet":"volunteers","desc":"AI assists volunteer matching"},{"planet":"campaigns","desc":"AI provides campaign insights"},{"planet":"gift_entry","desc":"AI assists gift entry"}]
},

action_plans: {
  packages: ["nonprofitcloud"],
  name: "Action Plans",
  icon: "\u{2705}",
  color: "#fb923c",
  description: "Action Plans in Nonprofit Cloud define and execute the tasks required for repeatable business processes. Templates establish task priorities, assignments, timing, and dependencies, while generated plans track individual work and overall completion against a target record. Action plans drive fundraising cultivation, automate program and case workflows, coordinate volunteer tasks, respond to campaign actions, and support grant review workflows. Stage Management complements action plans by tracking supported records through ordered stages and internal approvals.",
  components: [
    {id:"action-plan-templates",name:"Action Plan Templates",icon:"\u{1F4CB}",desc:"Action Plan Templates capture the repeatable tasks and other items required to complete a business process in Nonprofit Cloud. Templates can support processes such as fundraising activities, program steps, case workflows, volunteer activities, and grant review workflows. Template items define task details such as priority and timing, while the template identifies the type of record to which the resulting plan applies. Active templates provide a consistent foundation for creating action plans.",tags:["ActionPlanTemplate","ActionPlanTemplateItem"],docs:["Action plans define the tasks and other items needed to complete a business process. Action Plan Templates capture these repeatable requirements so that staff do not have to define the same process for each record. Nonprofit Cloud documentation identifies capital campaigns, research and development projects, other fundraising activities, and volunteer initiatives as examples of processes that can use action plans.","Each template item describes a task and can specify its priority and timing relative to the start of the plan. Template items can also identify dependencies between tasks through the preceding template item. The template identifies its target object type and must be active when used as the basis for operational plans.","For Volunteer Management, action plans can be applied to Application Form, Position, and Job Position records. The same template-driven approach supports cultivation in fundraising, program steps, case workflows, campaign-triggered processes, and grant review workflows. Administrators should define templates around repeatable organizational processes so that the generated work is consistent."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.fsc_action_plans.htm&type=5&language=en_US",connections:[{"planet":"programs","desc":"Templates automate program enrollment workflows"},{"planet":"volunteers","desc":"Templates automate volunteer onboarding"},{"planet":"fundraising","desc":"Templates drive cultivation step sequences"}]},
    {id:"action-plan-execution",name:"Action Plan Execution",icon:"\u{26A1}",desc:"Action Plan Execution applies a template-defined process to a target record and creates the tasks needed to perform that process. Each task includes a priority, an assignee, and information about when it must be completed. Staff update item statuses as work progresses, while the action plan records overall status and completion percentage. This execution model supports consistent work across fundraising, programs, case management, volunteer management, campaigns, and grantmaking.",tags:["ActionPlan","ActionPlanItem"],docs:["An action plan associates a selected template with a target record and a start date. The template items provide the repeatable task structure for the resulting plan. Each generated action plan item records its assignee, due date, status, and priority.","Users carry out the assigned tasks and update their statuses as the business process advances. The parent action plan tracks its own status and completion percentage, providing a summary of execution across the individual items. Due dates establish when assignees need to complete their work.","Action plans drive fundraising cultivation and can be triggered by campaign actions. They also automate program steps, case workflows, and volunteer tasks, and they support grant review workflows. In Volunteer Management, applicable target records include Application Form, Position, and Job Position."],connections:[{"planet":"case_management","desc":"Action plans automate case management workflows"}]},
    {id:"stage-management",name:"Stage Management",icon:"\u{1F4CA}",desc:"Stage Management tracks the progression of supported Nonprofit Cloud records through defined stages and internal processes. Stage definitions establish an ordered sequence for a particular object type and can associate an Action Plan Template with a stage. In Volunteer Management, stages can represent progress, preparation, fulfillment, review, and approval activities. Stage Management components must be added to the relevant Lightning record pages for users to work with stages.",tags:["StageDefinition"],docs:["Stage Management can track Volunteer Initiative, Job Position Assignment, Job Position Shift, Job Position, Position, and Application Form records. For Volunteer Initiatives, stages can follow progress and internal approvals from upcoming and in progress through completion. For Job Position Shifts, stages can help staff prepare for a shift and track whether it is upcoming or completed.","Stages can support Job Position and Position records as they move from development to fulfillment and through internal review. They can also track Job Position Assignments that require approvals or approval of volunteer hours, and Application Forms that require review and approval. Administrators add Stage Management components to Lightning record pages to expose this tracking to users.","A StageDefinition identifies the applicable object type, the stage's order, and its description. It can also reference an Action Plan Template, connecting a defined stage with a repeatable set of tasks. This structure allows stage tracking and action-plan execution to be configured together where the process requires both."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.stage_management.htm&language=en_US",connections:[{"planet":"volunteers","desc":"Stages track volunteer initiative and assignment progress"},{"planet":"grantmaking","desc":"Stages track application review progress"}]}
  ],
  dataFlow: ["Define an active Action Plan Template for the target business process.","Add ordered template items with task descriptions, priorities, timing offsets, and dependencies.","Apply or trigger the plan for fundraising cultivation, program steps, case workflows, volunteer tasks, campaign actions, or grant review workflows.","Assign generated action plan items to users and calculate their due dates from the plan start date.","Track item statuses, plan status, completion percentage, and applicable record stages.","Complete the assigned tasks and advance the target record through its configured process."],
  connections: [{"planet":"fundraising","desc":"Action plans drive cultivation"},{"planet":"programs","desc":"Action plans automate program steps"},{"planet":"case_management","desc":"Action plans automate case workflows"},{"planet":"volunteers","desc":"Action plans automate volunteer tasks"},{"planet":"campaigns","desc":"Campaign actions trigger plans"},{"planet":"grantmaking","desc":"Action plans support grant review workflows"}]
},

security: {
  packages: ["nonprofitcloud"],
  name: "Security & Access",
  icon: "\u{1F512}",
  color: "#64748b",
  description: "Security & Access manages licenses, permission assignments, and record access for Nonprofit Cloud. Administrators configure managed permission sets and permission set groups in Setup, supplementing them with custom or muting permission sets when organizational requirements differ from the defaults. Sharing settings and channel-specific permissions protect constituent records and control access to case, fundraising, volunteer, and other feature data.",
  components: [
    {id:"permission-set-groups",name:"Permission Set Groups",icon:"\u{1F511}",desc:"Permission set groups consolidate managed Nonprofit Cloud permissions with organization-specific additions or restrictions. Administrators assign the appropriate groups to individual users or multiple users based on the features they need. Combining managed, custom, and muting permission sets in groups preserves access to updated default permissions without requiring administrators to clone managed permission sets.",tags:["PermissionSetGroup"],docs:["Nonprofit Cloud provides managed permission sets for its features, and permission set groups can package the appropriate access for users. For example, users of Fundraising receive the applicable Fundraising permission set groups. Assignments can be made to a single user or multiple users through permission set assignment management.","A permission set group can include the applicable managed permission set together with custom and muting permission sets. This structure lets organizations add org-specific access or remove selected default permissions while continuing to receive updated Nonprofit Cloud permissions. It is the documented alternative to cloning the default permission sets."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_editions_and_permissions.htm&language=en_US",connections:[{"planet":"setup","desc":"Permission sets configured in Salesforce setup"}]},
    {id:"permission-set-licenses",name:"Permission Set Licenses",icon:"\u{1F4DC}",desc:"Permission set licenses provide prerequisites for access to certain Salesforce capabilities used with Nonprofit Cloud. Administrators must give users the required licenses before assigning related permissions. For gift acknowledgment document generation, administrators need the DocGen Designer permission set license and the SalesforceCRM Content User license.",tags:["PermissionSetLicense"],docs:["Some Nonprofit Cloud configurations depend on permission set licenses in addition to permission sets or permission set groups. Gift acknowledgment setup requires Salesforce administrators to have the DocGen Designer permission set license and the SalesforceCRM Content User license. All users who generate documents receive the DocGen User permission set.","Required licenses and permissions are assigned according to each user's responsibilities. If the DocGen permission set licenses aren't available in the Salesforce organization, the documentation directs customers to contact their Salesforce account executive. License assignment is therefore a prerequisite that administrators verify during feature setup."],connections:[{"planet":"setup","desc":"Licenses managed in setup"}]},
    {id:"data-security",name:"Data Security & Privacy",icon:"\u{1F6E1}",desc:"Data security and privacy controls determine who can access Nonprofit Cloud records and fields, including constituent and case data. Administrators configure user permissions and organization-wide sharing settings in Setup according to the access required for each feature. Experience Cloud users and guests receive dedicated permissions for supported external access scenarios.",tags:[],docs:["For Fundraising objects, administrators can set organization-wide sharing defaults to Public Read Only or, when broader access is appropriate, Public Read/Write. API integrations that access Fundraising objects use an API Integration user assigned the Fundraising Access permission set. Experience Cloud users can also receive permission sets that provide access to selected Fundraising objects and components.","Access to constituent records and case data is controlled through the permissions configured for the users who work with that information. Volunteer Management distinguishes between internal access, authenticated Experience Cloud access, and guest access by using the Manage Volunteer Data, Manage Volunteer Work in Experience Cloud, and Volunteer Management in Experience Cloud Guest Access permission sets. These assignments let administrators align data access with each user's role and access channel."],connections:[{"planet":"case_management","desc":"Case data requires strict access controls"},{"planet":"constituents","desc":"Donor and participant data is protected"}]},
    {id:"muting-permission-sets",name:"Custom & Muting Permission Sets",icon:"\u{1F507}",desc:"Custom permission sets add access required by organization-specific customizations, such as added fields. Muting permission sets remove selected permissions supplied by a default permission set. Administrators include both types alongside the applicable managed permission set in a permission set group rather than cloning the managed permission set.",tags:["PermissionSetGroup"],docs:["When an organization customizes a Nonprofit Cloud feature, administrators create a custom permission set for the additional permissions. Added fields are one documented reason to create this type of permission set. The custom permission set is then included in a permission set group with the appropriate managed permission set.","To remove permissions supplied by a default permission set, administrators create a muting permission set. They add the muting permission set to the same permission set group as the default and custom permission sets. This design preserves updates to the managed default permissions while allowing the organization to add or remove specific access."],docUrl:"https://help.salesforce.com/s/articleView?id=platform.perm_set_groups_muting.htm&language=en_US",connections:[{"planet":"setup","desc":"Custom permissions configured by admins"}]}
  ],
  dataFlow: ["Identify the Nonprofit Cloud features and data each user needs to access.","Assign any required permission set licenses in Setup.","Combine managed, custom, and muting permission sets in the appropriate permission set groups.","Assign permission sets or permission set groups to individual users or multiple users.","Configure sharing and external-access permissions to protect constituent records and control case data access.","Review assignments when features or organization-specific customizations change."],
  connections: [{"planet":"setup","desc":"Permissions configured in setup"},{"planet":"constituents","desc":"Data security protects constituent records"},{"planet":"case_management","desc":"Case data access controlled"}]
},

setup: {
  packages: ["nonprofitcloud"],
  name: "Setup & Configuration",
  icon: "\u{2699}",
  color: "#78716c",
  description: "Setup & Configuration is the central administration area for enabling and configuring Nonprofit Cloud capabilities, including Fundraising, Program Management, Volunteer Management, Case Management, Outcome Management, and optional Grantmaking. Administrators establish the constituent account model, relationship configuration, permissions, feature-specific settings, fundraising processes, picklists, record types, and sales processes. Data Processing Engine definitions transform organizational data into program and fundraising summaries, including gift designation rollups and campaign or outreach metrics. Scheduled automation keeps calculated results and actionable constituent segments current.",
  components: [
    {id:"feature-enablement",name:"Feature Enablement",icon:"\u{1F504}",desc:"Feature Enablement controls the foundational capabilities used across Nonprofit Cloud. Setup includes selecting an account model, configuring group memberships, assigning permissions, and turning on available features such as Fundraising, Interaction Summaries, Interest Tags, Record Alerts, Timeline, and Actionable Segmentation. Some choices, including enabling Person Accounts and Fundraising, can’t be reversed. Administrators can use Salesforce Go to discover, configure, and monitor available Nonprofit Cloud features and add-on licenses.",tags:[],docs:["Nonprofit Cloud commonly uses Person Accounts to represent individuals, Business Accounts to represent households and other groups, and Group Membership records to connect individuals and organizations. Person Accounts are strongly recommended for organizations using Fundraising or Program Management, but they aren’t required for Grantmaking. Grantmakers that primarily fund organizations and don’t use other Nonprofit Cloud feature areas can instead use the Contact and Business Account model. Because Person Accounts can’t be turned off after activation, administrators must evaluate the account model before enabling them.","Foundational setup includes configuring Data Processing Engine and enabling Actionable Segmentation, which uses summarized constituent data. Administrators can also enable Interaction Summaries, Interest Tags, Record Alerts, and Timeline to support stakeholder history, matching, detailed notes, and proactive follow-up. When Interaction Summaries are enabled, Role Hierarchy–Based Sharing for Interaction Summary and Interactions and the Enhanced Interaction Note Interface must also be enabled. Program, volunteer, case, relationship, and security settings should be configured for the corresponding Nonprofit Cloud workflows and user access.","Fundraising requires the Fundraising_Admin permission set group and must be turned on from Fundraising Settings. Salesforce recommends testing Fundraising in a sandbox because the feature can’t be turned off after activation. Other setup tasks can require feature-specific permission sets, object and field access, page-layout changes, or Flow permissions. Salesforce Go provides a streamlined location for discovering available Nonprofit Cloud features, accessing setup resources, completing configuration, and monitoring usage."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.npc_set_up_nonprofit_cloud.htm&type=5&language=en_US",connections:[{"planet":"programs","desc":"Program Management enabled in setup"},{"planet":"volunteers","desc":"Volunteer Management enabled in setup"},{"planet":"grantmaking","desc":"Grantmaking enabled in setup"}]},
    {id:"fundraising-settings",name:"Fundraising Settings",icon:"\u{1F4B0}",desc:"Fundraising Settings controls gift-processing behavior, donor lookup and matching, gift entry, and selected fundraising capabilities in Nonprofit Cloud. Administrators define the matching window for unpaid installments and the sequential transaction counts that cause commitments to become lapsed or failing. Settings can also automate recurring transaction creation and commitment closure, enable enhanced commitment processing, and configure Gift Entry Grid. Gift validations can be paused temporarily to reduce friction during bulk migrations.",tags:[],docs:["Installment Extension Day Count determines how many days before or after a due date an unpaid gift commitment transaction can match a received gift as an installment. Setting the count to zero creates an exact-date matching window and can incorrectly cause unpaid gifts to become lapsed. Lapsed Unpaid Transaction Count specifies how many sequential unpaid installments change a commitment to Lapsed, while Failing Transaction Count controls when sequential failed installments change it to Failing. A value of zero for either status threshold prevents that status update.","Administrators can select Create Recurring Schedule Transaction to automatically create the next transaction in a recurring schedule; otherwise, it must be created manually. Auto Close Recurring Commitment closes a recurring commitment after its schedule has ended when it has no ongoing or future schedule and no unpaid transactions. NextGen Commitment Processing enables enhanced concurrent processing for recurring gift commitments and is used with a scheduled flow. Administrators can also choose a custom external ID for donor lookup, use duplicate management rules for Business Process API donor matching, and turn on Gift Entry Grid.","Fundraising Settings can temporarily pause validations on gift transactions, gift commitments, and gift commitment schedules during bulk imports or migrations. These validation pauses should be disabled when migration is complete to preserve data integrity. Fundraising Settings also contains configuration used by RFM Score Calculation and can enable capabilities such as Gift Planning, Gift Agreements, and Philanthropic Research Topics in Agentforce. Outreach URL configuration uses organization-defined UTM parameters to identify the source, medium, and campaign associated with digital engagement."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.npc_fr_set_up_configure_fundraising.htm&language=en_US",connections:[{"planet":"gift_commitments","desc":"Processing thresholds affect commitment status"},{"planet":"gift_entry","desc":"Gift entry settings configured here"}]},
    {id:"data-processing-engine",name:"Data Processing Engine",icon:"\u{2699}",desc:"Data Processing Engine transforms data in a Nonprofit Cloud org and writes results that create or update records. Definitions can process data from standard objects, custom objects, and Analytics datasets to produce fundraising and program rollups. Fundraising templates calculate donor, gift designation, outreach, and actionable-list summaries, while a separate definition calculates RFM scores. Definitions can be run manually or invoked on a schedule through Flow.",tags:[],docs:["Data Processing Engine requires Data Pipelines and uses definitions to transform source data into calculated results. Nonprofit Cloud uses it to summarize information about donors, volunteers, fundraising efforts, and programs. These summaries support rollup fields and Actionable Segmentation. Users running definitions must have access to every object and field referenced by the definition.","Fundraising setup provides templates for DonorGiftSummary, GiftDesignation, OutreachSummary, and Fundraising Account Actionable List processing. Administrators clone each required template, save it under a new name, activate it, and run the definition with the required calendar date inputs. DonorGiftSummary supports donor and household giving rollups, GiftDesignation produces designation summaries, and OutreachSummary supplies campaign and outreach metrics. Definitions can optionally retain output record counts for selected nodes to support troubleshooting.","Administrators can use a schedule-triggered flow and the Manage Fundraising DPE Definitions action to update fundraising rollups automatically. The flow supplies calendar-year inputs, selects the definitions to run, handles returned batch job IDs, and can wait for job-completion events or follow a fault path. Batch Jobs and Monitor Workflow Services provide job progress and status information. RFM Score Calculation can likewise run manually or through a scheduled flow, with donor scores updated after each completed job."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.dpe_intro.htm&type=5",connections:[{"planet":"designations","desc":"DPE calculates designation rollup totals"},{"planet":"campaigns","desc":"DPE aggregates campaign performance metrics"}]},
    {id:"picklists-record-types",name:"Picklists & Record Types",icon:"\u{1F3F7}",desc:"Picklists & Record Types adapts Nonprofit Cloud records to an organization’s fundraising processes. Administrators can define values such as payment methods, review Gift Vehicle values, and add record types such as Pledge where appropriate. Opportunity record types, stage values, and sales processes can be configured for grant solicitation workflows. Related page layouts and permissions determine how users access the configured process.",tags:[],docs:["Fundraising administrators can create Payment Method picklist values to reflect the methods accepted by the organization. For in-kind gifts, they can review and modify Gift Vehicle picklist values on the Gift Commitment object. Gift entry custom-field mapping supports single-select picklist fields when the source and destination fields have compatible data types. Each mapping must use a unique source field and destination field.","Organizations that manage inbound grant solicitations can configure an Opportunity record type, stage values, and a corresponding Sales Process. Administrators can also create grant-specific Opportunity fields and assign a grant-specific page layout. For other gift workflows, an optional Pledge record type can be added to Gift Commitment. Users who need the resulting functionality must receive the required permissions and page-layout access."],connections:[{"planet":"fundraising","desc":"Opportunity record types define fundraising processes"},{"planet":"relationships","desc":"Relationship role picklists configured here"}]}
  ],
  dataFlow: ["Select the Person Account or Contact and Business Account model, then configure group memberships and relationship types.","Assign setup, feature, object, field, and flow permissions through the applicable permission sets and security configuration.","Enable the required Nonprofit Cloud features and configure program, volunteer, case, and stakeholder settings.","Configure Fundraising thresholds, recurring processing, donor matching, picklists, record types, and sales processes.","Enable Data Pipelines, then clone, activate, and run the required Data Processing Engine definitions.","Schedule Data Processing Engine jobs to refresh designation rollups, campaign metrics, donor scores, program summaries, and segmentation data."],
  connections: [{"planet":"fundraising","desc":"Fundraising settings"},{"planet":"programs","desc":"Program settings"},{"planet":"volunteers","desc":"Volunteer settings"},{"planet":"case_management","desc":"Case settings"},{"planet":"security","desc":"Permissions configured in setup"},{"planet":"constituents","desc":"Account model configured"},{"planet":"relationships","desc":"Relationship types configured"},{"planet":"designations","desc":"DPE calculates rollups"},{"planet":"campaigns","desc":"DPE aggregates metrics"}]
}

};
